INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('DKPL0001','VBPL001','Điều 23 khoản 1',E'Điều 23. Hợp đồng giao kết với người tiêu dùng, hợp đồng theo mẫu, điều \nkiện giao dịch chung \n1. Hình thức hợp đồng giao kết với người tiêu dùng, hợp đồng theo mẫu, điều \nkiện giao dịch chung được thực hiện theo quy định của pháp luật về dân sự và quy \nđịnh khác của pháp luật có liên quan. \n2. Ngôn ngữ, hình thức của hợp đồng giao kết với người tiêu dùng, hợp đồng \ntheo mẫu, điều kiện giao dịch chung trong trường hợp bằng văn bản phải được thể \nhiện rõ ràng, dễ hiểu. \nNgôn ngữ sử dụng trong hợp đồng giao kết với người tiêu dùng, hợp đồng theo \nmẫu, điều kiện giao dịch chung là tiếng Việt. Các bên có thể thỏa thuận sử dụng \nthêm tiếng dân tộc khác của Việt Nam hoặc tiếng nước ngoài. Trong trường hợp có \nsự khác biệt giữa bản tiếng Việt với bản tiếng dân tộc khác của Việt Nam hoặc bản \ntiếng nước ngoài, bản có lợi hơn cho người tiêu dùng được ưu tiên áp dụng. \n3. Hợp đồng theo mẫu phải có các nội dung cơ bản sau đây: \na) Thông tin của các bên trong hợp đồng bao gồm: tên, địa chỉ, số điện thoại, \nphương thức liên hệ khác (nếu có); \nb) Thông tin về sản phẩm, hàng hóa, dịch vụ được bán, cung cấp theo hợp đồng; \nc) Đo lường, số lượng, khối lượng, chất lượng, công dụng, giá của sản phẩm, \nhàng hóa, dịch vụ được bán, cung cấp, các thành phần cấu thành giá cuối cùng của \nsản phẩm, hàng hóa, dịch vụ nếu pháp luật có quy định phải công khai cấu thành \ngiá của sản phẩm, hàng hóa, dịch vụ;  \nd) Phương thức, thời hạn thanh toán; \nđ) Thời gian, địa điểm, phương thức bán, cung cấp sản phẩm, hàng hóa, dịch vụ; \ne) Quyền và nghĩa vụ của các bên bảo đảm tuân thủ quy định của Luật này và \nquy định khác của pháp luật có liên quan; \n\n \n \nCÔNG BÁO/Số 865 + 866/Ngày 30-7-2023 \n55 \n \ng) Trách nhiệm bảo vệ thông tin của người tiêu dùng; \nh) Trường hợp chấm dứt thực hiện hợp đồng và trách nhiệm phát sinh do chấm \ndứt thực hiện hợp đồng; \ni) Trường hợp bất khả kháng theo quy định của pháp luật; \nk) Phương thức giải quyết tranh chấp; \nl) Thời điểm giao kết hợp đồng, thời hạn của hợp đồng. \n4. Ngoài các nội dung cơ bản quy định tại khoản 3 Điều này, hợp đồng theo \nmẫu phải tuân thủ quy định của pháp luật khác có liên quan. \n5. Chính phủ quy định chi tiết khoản 2 Điều này.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2023/7/luat19_2023.pdf','AI_DOI_CHIEU_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_CHINH_THUC',NULL,NULL,'Rà soát 2026-10-07; đoạn toàn Điều; vị trí khoản/điểm riêng tại nguon_yeu_cau. Không xác nhận toàn bộ lịch sử sửa đổi.','KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('DKPL0228','VBPL011','Điều 121',E'Điều 121. Hợp đồng về nhà ở\nHợp đồng về nhà ở do các bên thỏa thuận và phải được lập thành văn bản bao gồm các nội dung sau đây:\n1. Họ và tên của cá nhân, tên của tổ chức và địa chỉ của các bên;\n2. Mô tả đặc điểm của nhà ở giao dịch và đặc điểm của thửa đất ở gắn với nhà ở đó. Đối với hợp đồng mua bán, hợp đồng thuê mua căn hộ chung cư thì các bên phải ghi rõ phần sở hữu chung, sử dụng chung; diện tích sử dụng thuộc quyền sở hữu riêng; diện tích sàn xây dựng căn hộ; mục đích sử dụng của phần sở hữu chung, sử dụng chung trong nhà chung cư theo đúng mục đích thiết kế đã được phê duyệt ban đầu;\n3. Giá trị góp vốn, giá giao dịch nhà ở nếu hợp đồng có thỏa thuận về giá; trường hợp mua bán, cho thuê, cho thuê mua nhà ở mà Nhà nước có quy định về giá thì các bên phải thực hiện theo quy định đó;\n4. Thời hạn và phương thức thanh toán tiền nếu là trường hợp mua bán, cho thuê, cho thuê mua, chuyển nhượng hợp đồng mua bán nhà ở;\n5. Thời gian giao nhận nhà ở; thời gian bảo hành nhà ở nếu là mua, thuê mua nhà ở được đầu tư xây dựng mới; thời hạn cho thuê, cho thuê mua, thế chấp, cho mượn, cho ở nhờ, ủy quyền quản lý nhà ở; thời hạn góp vốn;\n6. Quyền và nghĩa vụ của các bên;\n7. Cam kết của các bên;\n8. Các thỏa thuận khác;\n9. Thời điểm có hiệu lực của hợp đồng;\n10. Ngày, tháng, năm ký kết hợp đồng;\n11. Chữ ký và ghi rõ họ, tên của các bên, nếu là tổ chức thì phải đóng dấu (nếu có) và ghi rõ chức vụ của người ký.','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET','ARTICLE',NULL,NULL,'Trích toàn Điều từ file .doc người dùng cung cấp (65_2014_QH13.doc, sha256 tại SRC_DOC_VBPL011); đã kiểm số hiệu, ngày ban hành, hiệu lực Điều 181. Chưa đối chiếu bản Công báo; vị trí khoản/điểm tại nguon_yeu_cau.','USER_PROVIDED_SOURCE_PENDING_OFFICIAL_CHECK') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL005_23','VBPL005','Điều 23',E'Điều 23. Nguyên tắc kinh doanh nhà ở, công trình xây dựng hình thành \ntrong tương lai  \n1. Chủ đầu tư dự án bất động sản có quyền bán, cho thuê mua nhà ở, công trình \nxây dựng, phần diện tích sàn xây dựng trong công trình xây dựng hình thành trong \ntương lai trong dự án bất động sản theo quy định của Luật này. \n2. Việc mua bán, thuê mua nhà ở, công trình xây dựng, phần diện tích sàn xây \ndựng trong công trình xây dựng hình thành trong tương lai thực hiện theo các quy \nđịnh sau đây: \na) Tuân thủ các nguyên tắc quy định tại Điều 13 của Luật này; \nb) Đối tượng được mua, thuê mua nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai thực hiện theo \nquy định tại Điều 15 của Luật này; \nc) Giao dịch kinh doanh nhà ở, công trình xây dựng, phần diện tích sàn xây \ndựng trong công trình xây dựng hình thành trong tương lai thực hiện theo quy định \ntại Điều 16 của Luật này; \nd) Quyền của bên bán, cho thuê mua nhà ở, công trình xây dựng, phần diện \ntích sàn xây dựng trong công trình xây dựng hình thành trong tương lai thực hiện \ntheo quy định tại khoản 1 Điều 18 của Luật này; \nđ) Nghĩa vụ của bên bán, cho thuê mua nhà ở, công trình xây dựng, phần diện \ntích sàn xây dựng trong công trình xây dựng hình thành trong tương lai thực hiện \ntheo quy định tại các điểm a, b, c, d, đ, h, i, k, l, m, n, o, p, q khoản 1 và khoản 2 \nĐiều 19 của Luật này; \n\n \n46 \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n  \ne) Quyền của bên mua, thuê mua nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai thực hiện theo \nquy định tại khoản 1 và khoản 2 Điều 20 của Luật này; \ng) Nghĩa vụ của bên mua, thuê mua nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai thực hiện theo \nquy định tại các khoản 1, 2, 3 và 5 Điều 21 của Luật này; \nh) Tuân thủ quy định khác có liên quan của Luật này. \n3. Bảo đảm công khai, minh bạch; bảo vệ quyền và lợi ích hợp pháp của tổ \nchức, cá nhân đã ký kết hợp đồng mua bán, thuê mua nhà ở, công trình xây dựng, \nphần diện tích sàn xây dựng trong công trình xây dựng. \n4. Chủ đầu tư dự án bất động sản có trách nhiệm sau đây: \na) Trách nhiệm quy định tại Điều 17 của Luật này; \nb) Sử dụng tiền đã thu từ bên mua, thuê mua để đầu tư xây dựng dự án, nhà ở, \ncông trình xây dựng, phần diện tích sàn xây dựng trong công trình xây dựng đã \nđược bán, cho thuê mua đúng mục đích sử dụng theo thỏa thuận trong hợp đồng đã \nký kết; tuân thủ quy định của pháp luật về phòng, chống rửa tiền; \nc) Cung cấp công khai thông tin về tiến độ thực hiện đầu tư xây dựng nhà ở, \ncông trình xây dựng, phần diện tích sàn xây dựng trong công trình xây dựng cho \nbên mua, thuê mua theo hợp đồng mua bán, thuê mua đã ký kết hoặc cơ quan nhà \nnước có thẩm quyền khi có yêu cầu. Cung cấp đầy đủ, trung thực hồ sơ, thông tin \nvề bất động sản đủ điều kiện đưa vào kinh doanh theo quy định của Luật này cho \nsàn giao dịch bất động sản trong trường hợp lựa chọn phân phối sản phẩm thông \nqua sàn giao dịch bất động sản; \nd) Không ủy quyền cho tổ chức, cá nhân khác ký hợp đồng đặt cọc, hợp đồng \nmua bán, thuê mua nhà ở, công trình xây dựng, phần diện tích sàn xây dựng trong \ncông trình xây dựng hình thành trong tương lai. \n5. Chủ đầu tư dự án bất động sản chỉ được thu tiền đặt cọc không quá 5% giá \nbán, cho thuê mua nhà ở, công trình xây dựng, phần diện tích sàn xây dựng trong \ncông trình xây dựng từ bên đặt cọc để mua, thuê mua khi nhà ở, công trình xây \ndựng đã có đủ các điều kiện đưa vào kinh doanh theo quy định của Luật này. Thỏa \nthuận đặt cọc phải ghi rõ giá bán, cho thuê mua nhà ở, công trình xây dựng, phần \ndiện tích sàn xây dựng trong công trình xây dựng. \n\n \n \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n47','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','AI_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_THAM_CHIEU_KHONG_TU_AP_DUNG',25,27,NULL,'KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL005_25','VBPL005','Điều 25',E'Điều 25. Thanh toán trong mua bán, thuê mua nhà ở, công trình xây dựng \nhình thành trong tương lai \n1. Việc thanh toán trong mua bán nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai được thực hiện \nnhiều lần, lần đầu không quá 30% giá trị hợp đồng bao gồm cả tiền đặt cọc, những \nlần tiếp theo phải phù hợp với tiến độ xây dựng nhưng tổng số không quá 70% giá \ntrị hợp đồng khi chưa bàn giao nhà ở, công trình xây dựng, phần diện tích sàn xây \ndựng trong công trình xây dựng cho bên mua; trường hợp bên bán là tổ chức kinh \ntế có vốn đầu tư nước ngoài quy định tại khoản 4 Điều 10 của Luật này thì tổng số \nkhông quá 50% giá trị hợp đồng. \n2. Việc thanh toán trong thuê mua nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai được thực hiện \nnhiều lần, lần đầu không quá 30% giá trị hợp đồng bao gồm cả tiền đặt cọc, những \nlần tiếp theo phải phù hợp với tiến độ xây dựng đến khi bàn giao nhà ở, công trình \nxây dựng, phần diện tích sàn xây dựng trong công trình xây dựng cho bên thuê \nmua nhưng tổng số tiền thanh toán trước cho bên cho thuê mua không quá 50% \n\n \n \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n49 \n \ngiá trị hợp đồng thuê mua nhà ở, công trình xây dựng, phần diện tích sàn xây dựng \ntrong công trình xây dựng. Số tiền còn lại được tính thành tiền thuê để trả cho bên \ncho thuê mua trong một thời hạn nhất định theo thỏa thuận trong hợp đồng. \n3. Nếu bên mua, thuê mua chưa được cấp giấy chứng nhận về quyền sử dụng \nđất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về đất đai thì \nbên bán, cho thuê mua không được thu quá 95% giá trị hợp đồng; giá trị còn lại \ncủa hợp đồng được thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp giấy \nchứng nhận về quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy \nđịnh của pháp luật về đất đai cho bên mua, thuê mua.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','AI_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_THAM_CHIEU_KHONG_TU_AP_DUNG',28,29,NULL,'KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL005_46','VBPL005','Điều 46',E'Điều 46. Nội dung chính của hợp đồng trong kinh doanh bất động sản  \n1. Hợp đồng mua bán, thuê, thuê mua nhà ở, công trình xây dựng phải có các \nnội dung chính sau đây:  \na) Tên, địa chỉ của các bên;  \nb) Các thông tin về bất động sản;  \nc) Giá bán, cho thuê, cho thuê mua;  \nd) Phương thức và thời hạn thanh toán;  \nđ) Bảo lãnh của ngân hàng bảo lãnh cho nghĩa vụ tài chính của chủ đầu tư đối \nvới trường hợp bán nhà ở hình thành trong tương lai;  \ne) Thời hạn giao, nhận bất động sản và hồ sơ kèm theo;  \ng) Bảo hành;  \nh) Quyền, nghĩa vụ của các bên;  \ni) Trách nhiệm do vi phạm hợp đồng;  \nk) Phạt vi phạm hợp đồng;  \nl) Các trường hợp chấm dứt, hủy bỏ hợp đồng và biện pháp xử lý;  \nm) Phương thức giải quyết tranh chấp;  \nn) Thời điểm có hiệu lực của hợp đồng. \n2. Hợp đồng chuyển nhượng, cho thuê quyền sử dụng đất đã có hạ tầng kỹ \nthuật trong dự án bất động sản phải có các nội dung chính sau đây: \na) Tên, địa chỉ của các bên;  \n\n \n \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n67 \n \nb) Các thông tin về loại đất, diện tích, vị trí, số hiệu, ranh giới và tình trạng \nthửa đất, tài sản gắn liền với đất (nếu có);  \nc) Thời hạn sử dụng đất; giá chuyển nhượng, cho thuê, cho thuê lại quyền sử \ndụng đất, bao gồm tài sản gắn liền với đất (nếu có);  \nd) Phương thức và thời hạn thanh toán;  \nđ) Thời hạn bàn giao đất và hồ sơ kèm theo;  \ne) Quyền, nghĩa vụ của các bên;  \ng) Quyền của bên thứ ba đối với thửa đất (nếu có);  \nh) Trách nhiệm do vi phạm hợp đồng;  \ni) Phạt vi phạm hợp đồng;  \nk) Giải quyết hậu quả khi hợp đồng hết hạn đối với trường hợp cho thuê, cho \nthuê lại quyền sử dụng đất;  \nl) Các trường hợp chấm dứt, hủy bỏ hợp đồng và biện pháp xử lý;  \nm) Phương thức giải quyết tranh chấp; \nn) Thời điểm có hiệu lực của hợp đồng. \n3. Hợp đồng chuyển nhượng toàn bộ hoặc một phần dự án bất động sản phải \ncó các nội dung chính sau đây:  \na) Tên, địa chỉ của các bên;  \nb) Thông tin cơ bản của dự án đã được phê duyệt;  \nc) Thông tin chi tiết về toàn bộ dự án hoặc phần dự án chuyển nhượng;  \nd) Giá chuyển nhượng;  \nđ) Phương thức và thời hạn thanh toán;  \ne) Thời hạn bàn giao toàn bộ hoặc một phần dự án và hồ sơ kèm theo; \ng) Quyền, nghĩa vụ của các bên;  \nh) Trách nhiệm của các bên trong việc thực hiện các thủ tục hành chính liên \nquan đến quyền sử dụng đất;  \ni) Trách nhiệm do vi phạm hợp đồng;  \nk) Phạt vi phạm hợp đồng;  \nl) Các trường hợp chấm dứt hợp đồng và biện pháp xử lý;  \nm) Phương thức giải quyết tranh chấp;  \nn) Thời điểm có hiệu lực của hợp đồng. \n\n \n68 \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n  \n4. Hợp đồng kinh doanh dịch vụ bất động sản phải có các nội dung chính \nsau đây: \na) Tên, địa chỉ của các bên;  \nb) Đối tượng và nội dung dịch vụ;  \nc) Yêu cầu và kết quả dịch vụ;  \nd) Thời hạn thực hiện dịch vụ;  \nđ) Phí dịch vụ, thù lao, hoa hồng dịch vụ;  \ne) Phương thức và thời hạn thanh toán;  \ng) Quyền, nghĩa vụ của các bên;  \nh) Phương thức giải quyết tranh chấp; \ni) Thời điểm có hiệu lực của hợp đồng.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','AI_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_THAM_CHIEU_KHONG_TU_AP_DUNG',46,48,NULL,'KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL007_129','VBPL007','Điều 129',E'Điều 129. Bảo hành nhà ở\n    1. Tổ chức, cá nhân thi công xây dựng nhà ở phải bảo hành nhà ở theo quy\nđịnh của pháp luật về xây dựng; tổ chức, cá nhân cung ứng trang thiết bị nhà ở\nphải bảo hành trang thiết bị theo thời hạn do nhà sản xuất quy định.\n    Trường hợp đầu tư xây dựng nhà ở để bán, cho thuê mua thì bên bán, bên cho\nthuê mua nhà ở có trách nhiệm bảo hành nhà ở theo quy định tại khoản 2 và khoản 3\nĐiều này. Bên bán, bên cho thuê mua nhà ở có quyền yêu cầu tổ chức, cá nhân thi công\nxây dựng, cung ứng trang thiết bị thực hiện trách nhiệm bảo hành theo quy định\ncủa pháp luật.\n    2. Nhà ở được bảo hành kể từ khi hoàn thành việc xây dựng và nghiệm thu đưa\nvào sử dụng với thời hạn như sau:\n     a) Đối với nhà chung cư thì tối thiểu là 60 tháng;\n     b) Đối với nhà ở riêng lẻ thì tối thiểu là 24 tháng.\n    3. Nội dung bảo hành nhà ở bao gồm sửa chữa, khắc phục các hư hỏng khung,\ncột, dầm, sàn, tường, trần, mái, sân thượng, cầu thang bộ, các phần ốp, lát, trát, hệ\nthống cung cấp chất đốt, hệ thống cấp điện sinh hoạt, cấp điện chiếu sáng, bể nước\nvà hệ thống cấp nước sinh hoạt, bể phốt và hệ thống thoát nước thải, chất thải sinh\nhoạt, khắc phục các trường hợp nghiêng, lún, nứt, sụt nhà ở và các nội dung khác\ntheo thỏa thuận trong hợp đồng mua bán, thuê mua nhà ở. Đối với các trang thiết\nbị khác gắn với nhà ở thì bên bán, bên cho thuê mua nhà ở thực hiện bảo hành sửa\nchữa, thay thế theo thời hạn quy định của nhà sản xuất.\n\n                    CÔNG BÁO/Số 39 + 40/Ngày 08-01-2024                         13','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','OFFICIAL_TEXT_EXTRACTED_PENDING_HUMAN','ARTICLE',NULL,NULL,'Bản gốc 2023. Hiệu lực Điều 197 đã sửa bởi Luật 43/2024; tham chiếu văn bản hợp nhất khi xét sửa đổi.','OFFICIAL_SOURCE') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL007_152','VBPL007','Điều 152',E'Điều 152. Kinh phí bảo trì của nhà chung cư có nhiều chủ sở hữu\n    1. Đối với căn hộ, phần diện tích khác trong nhà chung cư mà chủ đầu tư dự án\nđầu tư xây dựng nhà ở bán, cho thuê mua thì người mua, thuê mua phải đóng kinh\nphí bảo trì là 2% giá trị căn hộ, phần diện tích bán, cho thuê mua này; khoản tiền\nnày được tính riêng với tiền bán, tiền thuê mua căn hộ, phần diện tích khác trong\nnhà chung cư và được quy định rõ trong hợp đồng mua bán, hợp đồng thuê mua.\n    2. Đối với căn hộ, phần diện tích khác trong nhà chung cư mà chủ đầu tư dự án\nđầu tư xây dựng nhà ở giữ lại không bán, không cho thuê mua hoặc chưa bán, chưa\ncho thuê mua tính tại thời điểm bàn giao đưa nhà chung cư vào sử dụng, trừ phần\ndiện tích thuộc sở hữu chung thì chủ đầu tư dự án đầu tư xây dựng nhà ở phải đóng\nkinh phí bảo trì là 2% giá trị căn hộ, phần diện tích giữ lại; phần giá trị này được\ntính theo giá bán căn hộ có giá cao nhất của nhà chung cư đó tại thời điểm bàn giao\nđưa nhà chung cư vào sử dụng.\n    3. Trường hợp chủ đầu tư dự án đầu tư xây dựng nhà ở ký hợp đồng mua bán,\nthuê mua căn hộ hoặc phần diện tích khác trong nhà chung cư trước ngày 01 tháng 7\nnăm 2006 mà chưa thu kinh phí bảo trì thì các chủ sở hữu nhà chung cư họp Hội\nnghị nhà chung cư để thống nhất mức đóng góp kinh phí này; mức đóng góp kinh\nphí có thể được nộp hằng tháng vào tài khoản tại tổ chức tín dụng hoặc chi nhánh\nngân hàng nước ngoài đang hoạt động tại Việt Nam do Ban quản trị nhà chung cư\nlập hoặc được đóng khi phát sinh công việc cần bảo trì.\n\n30                  CÔNG BÁO/Số 39 + 40/Ngày 08-01-2024\n\n    4. Trường hợp chủ đầu tư dự án đầu tư xây dựng nhà ở ký hợp đồng mua bán,\nthuê mua căn hộ hoặc phần diện tích khác trong nhà chung cư kể từ ngày 01 tháng 7\nnăm 2006 đến trước ngày Luật này có hiệu lực thi hành mà trong hợp đồng mua bán,\nthuê mua căn hộ, phần diện tích khác trong nhà chung cư không có thỏa thuận về kinh\nphí bảo trì thì chủ đầu tư dự án đầu tư xây dựng nhà ở phải đóng khoản tiền này;\ntrường hợp trong hợp đồng mua bán, thuê mua căn hộ, phần diện tích khác trong nhà\nchung cư mà giá mua, giá thuê mua chưa tính kinh phí bảo trì thì chủ sở hữu thực hiện\nđóng khoản kinh phí bảo trì theo quy định tại khoản 3 Điều này.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','OFFICIAL_TEXT_EXTRACTED_PENDING_HUMAN','ARTICLE',NULL,NULL,'Bản gốc 2023. Hiệu lực Điều 197 đã sửa bởi Luật 43/2024; tham chiếu văn bản hợp nhất khi xét sửa đổi.','OFFICIAL_SOURCE') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL011_85','VBPL011','Điều 85',E'Điều 85. Bảo hành nhà ở\n1. Tổ chức, cá nhân thi công xây dựng nhà ở phải bảo hành nhà ở theo quy định của pháp luật về xây dựng; tổ chức, cá nhân cung ứng thiết bị nhà ở phải bảo hành thiết bị theo thời hạn do nhà sản xuất quy định.\nTrường hợp đầu tư xây dựng nhà ở để bán, cho thuê mua thì bên bán, bên cho thuê mua nhà ở có trách nhiệm bảo hành nhà ở theo quy định tại khoản 2 và khoản 3 Điều này. Bên bán, bên cho thuê mua nhà ở có quyền yêu cầu tổ chức, cá nhân thi công xây dựng, cung ứng thiết bị thực hiện trách nhiệm bảo hành theo quy định của pháp luật.\n2. Nhà ở được bảo hành kể từ khi hoàn thành việc xây dựng và nghiệm thu đưa vào sử dụng với thời hạn như sau:\na) Đối với nhà chung cư thì tối thiểu là 60 tháng;\nb) Đối với nhà ở riêng lẻ thì tối thiểu là 24 tháng.\n3. Nội dung bảo hành nhà ở bao gồm sửa chữa, khắc phục các hư hỏng khung, cột, dầm, sàn, tường, trần, mái, sân thượng, cầu thang bộ, các phần ốp, lát, trát, hệ thống cung cấp chất đốt, hệ thống cấp điện sinh hoạt, cấp điện chiếu sáng, bể nước và hệ thống cấp nước sinh hoạt, bể phốt và hệ thống thoát nước thải, chất thải sinh hoạt, khắc phục các trường hợp nghiêng, lún, nứt, sụt nhà ở và các nội dung khác theo thỏa thuận trong hợp đồng mua bán, thuê mua nhà ở. Đối với các thiết bị khác gắn với nhà ở thì bên bán, bên cho thuê mua nhà ở thực hiện bảo hành sửa chữa, thay thế theo thời hạn quy định của nhà sản xuất.','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET','ARTICLE',NULL,NULL,'Trích toàn Điều từ file .doc người dùng cung cấp (65_2014_QH13.doc, sha256 tại SRC_DOC_VBPL011); đã kiểm số hiệu, ngày ban hành, hiệu lực Điều 181. Chưa đối chiếu bản Công báo; vị trí khoản/điểm tại nguon_yeu_cau.','USER_PROVIDED_SOURCE_PENDING_OFFICIAL_CHECK') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL011_108','VBPL011','Điều 108',E'Điều 108. Kinh phí bảo trì phần sở hữu chung của nhà chung cư có nhiều chủ sở hữu\n1. Kinh phí bảo trì phần sở hữu chung của nhà chung cư có nhiều chủ sở hữu được quy định như sau:\na) Đối với căn hộ, phần diện tích khác trong nhà chung cư mà chủ đầu tư bán, cho thuê mua thì chủ đầu tư phải đóng 2% giá trị căn hộ hoặc diện tích khác bán, cho thuê mua; khoản tiền này được tính vào tiền bán, tiền thuê mua nhà mà người mua, thuê mua phải đóng khi nhận bàn giao và được quy định rõ trong hợp đồng mua bán, hợp đồng thuê mua;\nb) Đối với căn hộ, phần diện tích khác trong nhà chung cư mà chủ đầu tư giữ lại không bán, không cho thuê mua hoặc chưa bán, chưa cho thuê mua tính đến thời điểm bàn giao đưa nhà chung cư vào sử dụng, trừ phần diện tích thuộc sở hữu chung thì chủ đầu tư phải đóng 2% giá trị căn hộ, phần diện tích giữ lại; phần giá trị này được tính theo giá bán căn hộ có giá cao nhất của nhà chung cư đó.\n2. Trường hợp kinh phí bảo trì quy định tại khoản 1 Điều này không đủ để thực hiện bảo trì phần sở hữu chung của nhà chung cư thì các chủ sở hữu nhà chung cư có trách nhiệm đóng góp thêm kinh phí tương ứng với phần diện tích thuộc sở hữu riêng của từng chủ sở hữu.\n3. Trường hợp chủ đầu tư ký hợp đồng mua bán, thuê mua căn hộ hoặc diện tích khác trong nhà chung cư trước ngày 01 tháng 7 năm 2006 mà chưa thu kinh phí bảo trì phần sở hữu chung thì các chủ sở hữu nhà chung cư họp Hội nghị nhà chung cư để thống nhất mức đóng góp kinh phí này; mức đóng góp kinh phí có thể được nộp hằng tháng vào tài khoản tiền gửi tại tổ chức tín dụng đang hoạt động tại Việt Nam do Ban quản trị nhà chung cư lập hoặc được đóng khi phát sinh công việc cần bảo trì.\n4. Trường hợp chủ đầu tư ký hợp đồng mua bán, thuê mua căn hộ hoặc diện tích khác trong nhà chung cư sau ngày 01 tháng 7 năm 2006 mà trong hợp đồng mua bán, thuê mua nhà ở không có thỏa thuận về kinh phí bảo trì thì chủ đầu tư phải đóng khoản tiền này; trường hợp trong hợp đồng mua bán, thuê mua nhà ở mà giá mua, giá thuê mua chưa tính kinh phí bảo trì thì chủ sở hữu thực hiện đóng khoản kinh phí bảo trì phần sở hữu chung theo quy định tại khoản 3 Điều này.\n5. Trường hợp nhà chung cư có mục đích sử dụng hỗn hợp để ở và kinh doanh mà phân chia được riêng biệt các khu chức năng khác nhau trong cùng một tòa nhà bao gồm khu chức năng căn hộ, khu chức năng kinh doanh, dịch vụ và mỗi khu chức năng này có phần sở hữu chung được tách biệt với phần sở hữu chung của cả tòa nhà, được quản lý, vận hành độc lập thì chủ đầu tư và người mua, thuê mua căn hộ hoặc diện tích khác trong nhà chung cư thỏa thuận trong hợp đồng mua bán, thuê mua việc phân chia tỷ lệ kinh phí bảo trì phần sở hữu chung thành nhiều phần để quản lý, sử dụng theo quy định tại khoản 4 Điều 109 của Luật này.','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET','ARTICLE',NULL,NULL,'Trích toàn Điều từ file .doc người dùng cung cấp (65_2014_QH13.doc, sha256 tại SRC_DOC_VBPL011); đã kiểm số hiệu, ngày ban hành, hiệu lực Điều 181. Chưa đối chiếu bản Công báo; vị trí khoản/điểm tại nguon_yeu_cau.','USER_PROVIDED_SOURCE_PENDING_OFFICIAL_CHECK') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL010_18','VBPL010','Điều 18',E'Điều 18. Nội dung hợp đồng mua bán, cho thuê, cho thuê mua nhà, công trình xây dựng\nHợp đồng mua bán, cho thuê, cho thuê mua nhà, công trình xây dựng phải có các nội dung chính sau đây:\n1. Tên, địa chỉ của các bên;\n2. Các thông tin về bất động sản;\n3. Giá mua bán, cho thuê, cho thuê mua;\n4. Phương thức và thời hạn thanh toán;\n5. Thời hạn giao, nhận bất động sản và hồ sơ kèm theo;\n6. Bảo hành;\n7. Quyền và nghĩa vụ của các bên;\n8. Trách nhiệm do vi phạm hợp đồng;\n9. Phạt vi phạm hợp đồng;\n10. Các trường hợp chấm dứt, hủy bỏ hợp đồng và các biện pháp xử lý;\n11. Giải quyết tranh chấp;\n12. Thời điểm có hiệu lực của hợp đồng.','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET','ARTICLE',NULL,NULL,'Trích toàn Điều từ 66_2014_QH13.doc (SRC_DOC_VBPL010). Chưa đối chiếu Công báo.','USER_PROVIDED_SOURCE_PENDING_OFFICIAL_CHECK') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL010_57','VBPL010','Điều 57',E'Điều 57. Thanh toán trong mua bán, thuê mua bất động sản hình thành trong tương lai\n1. Việc thanh toán trong mua bán, thuê mua bất động sản hình thành trong tương lai được thực hiện nhiều lần, lần đầu không quá 30% giá trị hợp đồng, những lần tiếp theo phải phù hợp với tiến độ xây dựng bất động sản nhưng tổng số không quá 70% giá trị hợp đồng khi chưa bàn giao nhà, công trình xây dựng cho khách hàng; trường hợp bên bán, bên cho thuê mua là doanh nghiệp có vốn đầu tư nước ngoài thì tổng số không quá 50% giá trị hợp đồng.\nTrường hợp bên mua, bên thuê mua chưa được cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu nhà ở và tài sản khác gắn liền với đất thì bên bán, bên cho thuê mua không được thu quá 95% giá trị hợp đồng; giá trị còn lại của hợp đồng được thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu nhà ở và tài sản khác gắn liền với đất cho bên mua, bên thuê mua.\n2. Chủ đầu tư phải sử dụng tiền ứng trước của khách hàng theo đúng mục đích đã cam kết.','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET','ARTICLE',NULL,NULL,'Trích toàn Điều từ 66_2014_QH13.doc (SRC_DOC_VBPL010). Chưa đối chiếu Công báo.','USER_PROVIDED_SOURCE_PENDING_OFFICIAL_CHECK') ON CONFLICT ("dieu_khoan_id") DO NOTHING;
