INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_FIRST_PAYMENT_CAP','Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc.','G_THANH_TOAN','THEO_NHOM_PHIEN_BAN_KHONG_LOAI_TRU_NGUON_DONG_THOI','KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_PRE_HANDOVER_CAP','Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%.','G_THANH_TOAN','THEO_NHOM_PHIEN_BAN_KHONG_LOAI_TRU_NGUON_DONG_THOI','KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_PRE_CERT_CAP','Nếu người mua chưa được cấp Giấy chứng nhận thì bên bán không được thu quá 95% giá trị hợp đồng; phần còn lại thanh toán khi Giấy chứng nhận được cấp.','G_THANH_TOAN','THEO_NHOM_PHIEN_BAN_KHONG_LOAI_TRU_NGUON_DONG_THOI','KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_MAINTENANCE_2_PERCENT','Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng.','J_GIA_THANH_TOAN_BAO_TRI','THEO_NHOM_PHIEN_BAN_KHONG_LOAI_TRU_NGUON_DONG_THOI','KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_WARRANTY_MIN_60','Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng.','O_BAO_HANH','THEO_NHOM_PHIEN_BAN_KHONG_LOAI_TRU_NGUON_DONG_THOI','KE_THUA_CHUA_XAC_MINH') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_APT_DEPOSIT','Đặt cọc không quá 5% giá bán và chỉ khi căn hộ tương lai đủ điều kiện kinh doanh; thỏa thuận đặt cọc ghi rõ giá bán.','CAN_HO','ALL_MANDATORY','SOURCE_CURATED_PENDING_HUMAN') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."yeu_cau_phap_ly" ("requirement_id","ten_nhom_yeu_cau","nhom_nghia_vu","che_do_ket_hop","loai_du_lieu") VALUES ('FAM_APT_COMMERCIAL_CONTENT','Hợp đồng kinh doanh căn hộ có nội dung chính theo Điều 46 khoản 1, gồm các bên, căn hộ, giá, thanh toán, bàn giao, bảo hành, trách nhiệm, chấm dứt, tranh chấp và hiệu lực.','CAN_HO','ALL_MANDATORY','SOURCE_CURATED_PENDING_HUMAN') ON CONFLICT ("requirement_id") DO NOTHING;
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_GYC005','FAM_PARTY_IDENTITY','BVNTD','Phải có tên, địa chỉ, số điện thoại và phương thức liên hệ khác của các bên nếu có.','VBPL001','DKPL0001','2024-07-01'::date,NULL,'NOI_DUNG_BAT_BUOC_CO_DIEU_KIEN','Quan hệ doanh nghiệp/chủ thể kinh doanh với người tiêu dùng theo Điều 3 Luật 19/2023; mục đích tiêu dùng, sinh hoạt, không thương mại phải có căn cứ. Nội dung Điều 23 khoản 3 chỉ bắt buộc trong hợp đồng theo mẫu thực tế. Xác nhận phiên bản và chuyển tiếp tại mốc nghĩa vụ.','Doanh nghiệp','HOP_DONG_PHU_LUC_VA_NGUON_LUAT','Đánh giá các tiêu chí TC_PV_GYC005_01, TC_PV_GYC005_02, TC_PV_GYC005_03. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Xét Điều 80 Luật 19/2023; danh mục QĐ07 đến trước 01/07/2025, TT42 từ 01/07/2025; cần xác minh nghĩa vụ tại thời điểm sử dụng mẫu/nhận tiền.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_XAC_LAP_HOAC_SU_DUNG_MAU','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
