INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_HYC036','FAM_PRE_HANDOVER_CAP','KDBDS','Trước khi bàn giao, tổng số tiền thu đối với bất động sản hình thành trong tương lai không vượt quá 70% giá trị hợp đồng; nếu bên bán là doanh nghiệp có vốn đầu tư nước ngoài thì không vượt quá 50%.','VBPL010','ART_VBPL010_57','2015-07-01'::date,'2024-08-01'::date,'BAT_BUOC','Căn hộ hình thành trong tương lai, thanh toán nhiều lần','Bên bán','NOI_DUNG_HOP_DONG','Đánh giá các tiêu chí TC_PV_HYC036_01 (AI soạn nháp 2026-10-11, chưa duyệt). Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1. Ngưỡng 50% xét ben_ban_co_von_nuoc_ngoai (numeric_rule.seller_fact).','Nếu tổng thu trước bàn giao >70% (hoặc >50% với trường hợp FDI thuộc luật định) thì NON_COMPLIANT.','Thiếu nguồn đúng phiên bản => INSUFFICIENT. Không mượn luật mới để gán nhãn luật cũ.','CHUA_XAC_MINH_CHI_TIET_KHONG_TU_AP_LUAT_MOI_HOI_TO','AI_DRAFT_PENDING_HUMAN','CHUA_XAC_MINH','CAN_BIEN_SOAN_THEO_TUNG_NGHIA_VU','AI_DRAFT_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_HYC037','FAM_PRE_CERT_CAP','KDBDS','Khi người mua chưa được cấp Giấy chứng nhận, bên bán không được thu quá 95% giá trị hợp đồng; phần còn lại thanh toán khi được cấp Giấy chứng nhận.','VBPL010','ART_VBPL010_57','2015-07-01'::date,'2024-08-01'::date,'BAT_BUOC','Chưa cấp Giấy chứng nhận','Bên bán','NOI_DUNG_HOP_DONG','Đánh giá các tiêu chí TC_PV_HYC037_01, TC_PV_HYC037_02 (AI soạn nháp 2026-10-11, chưa duyệt). Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Bất kỳ clause hoặc exception nào làm Bên Mua phải thanh toán >95% trước khi cơ quan có thẩm quyền cấp Giấy chứng nhận => NON_COMPLIANT, kể cả khi clause khác ghi đúng trần 95%.','Thiếu nguồn đúng phiên bản => INSUFFICIENT. Không mượn luật mới để gán nhãn luật cũ.','CHUA_XAC_MINH_CHI_TIET_KHONG_TU_AP_LUAT_MOI_HOI_TO','AI_DRAFT_PENDING_HUMAN','CHUA_XAC_MINH','CAN_BIEN_SOAN_THEO_TUNG_NGHIA_VU','AI_DRAFT_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
