INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_HYC049','FAM_MAINTENANCE_2_PERCENT','NHAO','Đối với căn hộ/phần diện tích bán hoặc thuê mua trong nhà chung cư nhiều chủ sở hữu, kinh phí bảo trì phần sở hữu chung bằng 2% giá trị và phải được quy định rõ trong hợp đồng.','VBPL011','ART_VBPL011_108','2015-07-01'::date,'2024-08-01'::date,'BAT_BUOC','Nhà chung cư có nhiều chủ sở hữu','Chủ đầu tư/Bên mua','NOI_DUNG_HOP_DONG','Đánh giá các tiêu chí TC_PV_HYC049_01, TC_PV_HYC049_02, TC_PV_HYC049_03 (AI soạn nháp 2026-10-11, chưa duyệt). Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Kinh phí bảo trì không bằng 2% hoặc không được quy định rõ theo căn cứ tính luật định => NON_COMPLIANT/PARTIAL tùy evidence.','Thiếu nguồn đúng phiên bản => INSUFFICIENT. Không mượn luật mới để gán nhãn luật cũ.','CHUA_XAC_MINH_CHI_TIET_KHONG_TU_AP_LUAT_MOI_HOI_TO','AI_DRAFT_PENDING_HUMAN','CHUA_XAC_MINH','CAN_BIEN_SOAN_THEO_TUNG_NGHIA_VU','AI_DRAFT_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_HYC053','FAM_WARRANTY_MIN_60','NHAO','Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng.','VBPL011','ART_VBPL011_85','2015-07-01'::date,'2024-08-01'::date,'BAT_BUOC','Nhà chung cư','Bên bán','NOI_DUNG_HOP_DONG','Đánh giá các tiêu chí TC_PV_HYC053_01, TC_PV_HYC053_02 (AI soạn nháp 2026-10-11, chưa duyệt). Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Nếu thời hạn bảo hành nhà chung cư <60 tháng thì NON_COMPLIANT.','Thiếu nguồn đúng phiên bản => INSUFFICIENT. Không mượn luật mới để gán nhãn luật cũ.','CHUA_XAC_MINH_CHI_TIET_KHONG_TU_AP_LUAT_MOI_HOI_TO','AI_DRAFT_PENDING_HUMAN','CHUA_XAC_MINH','CAN_BIEN_SOAN_THEO_TUNG_NGHIA_VU','AI_DRAFT_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_APT_DEPOSIT_2024','FAM_APT_DEPOSIT','CAN_HO_2024','Đặt cọc không quá 5% giá bán và chỉ khi căn hộ tương lai đủ điều kiện kinh doanh; thỏa thuận đặt cọc ghi rõ giá bán.','VBPL005','ART_VBPL005_23','2024-08-01'::date,NULL,'BAT_BUOC_CO_DIEU_KIEN','FUTURE_COMMERCIAL Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Theo từng điều và tư cách các bên','HOP_DONG_VA_PHU_LUC; CHUNG_TU_THUC_HIEN_KHI_NGHIA_VU_PHAT_SINH','Đánh giá các tiêu chí TC_APT_DEPOSIT_CAP, TC_APT_DEPOSIT_ELIGIBLE, TC_APT_DEPOSIT_PRICE. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Xác định luật hợp đồng tại ngày xác lập, ngày thu/đến hạn và chuyển tiếp Điều 83; không tự hồi tố trần luật mới vào hợp đồng đã xác lập theo luật cũ.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_THOA_THUAN_VA_NGAY_THU_TIEN','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_APT_COMMERCIAL_CONTENT_2024','FAM_APT_COMMERCIAL_CONTENT','CAN_HO_2024','Hợp đồng kinh doanh căn hộ có nội dung chính theo Điều 46 khoản 1, gồm các bên, căn hộ, giá, thanh toán, bàn giao, bảo hành, trách nhiệm, chấm dứt, tranh chấp và hiệu lực.','VBPL005','ART_VBPL005_46','2024-08-01'::date,NULL,'BAT_BUOC_CO_DIEU_KIEN','COMMERCIAL Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Theo từng điều và tư cách các bên','HOP_DONG_PHU_LUC_VA_NGUON_LUAT','Đánh giá các tiêu chí TC_APT_COMMERCIAL_CONTENT_PARTIES, TC_APT_COMMERCIAL_CONTENT_PROPERTY, TC_APT_COMMERCIAL_CONTENT_PRICE, TC_APT_COMMERCIAL_CONTENT_METHOD, TC_APT_COMMERCIAL_CONTENT_TERM, TC_APT_COMMERCIAL_CONTENT_HANDOVER, TC_APT_COMMERCIAL_CONTENT_WARRANTY, TC_APT_COMMERCIAL_CONTENT_RIGHTS, TC_APT_COMMERCIAL_CONTENT_LIABILITY, TC_APT_COMMERCIAL_CONTENT_PENALTY, TC_APT_COMMERCIAL_CONTENT_TERMINATION, TC_APT_COMMERCIAL_CONTENT_DISPUTE, TC_APT_COMMERCIAL_CONTENT_EFFECT. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Luật 29/2023 Điều 83 và Luật Nhà ở Điều 198; xác nhận chuyển tiếp trước khi chọn bản 2024.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_XAC_LAP_HOAC_SU_DUNG_MAU','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true) ON CONFLICT ("requirement_version_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC005_01','PV_GYC005',1,'Tên bên bán và bên mua xác định được.','NOI_DUNG_BAT_BUOC','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_GYC005","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Tên bên bán và bên mua xác định được. Hồ sơ liên quan: tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','DKPL0001','19/2023/QH15; Điều 23 khoản 3 điểm a','https://datafiles.chinhphu.vn/cpp/files/vbpq/2023/7/luat19_2023.pdf','Quan hệ doanh nghiệp/chủ thể kinh doanh với người tiêu dùng theo Điều 3 Luật 19/2023; mục đích tiêu dùng, sinh hoạt, không thương mại phải có căn cứ. Nội dung Điều 23 khoản 3 chỉ bắt buộc trong hợp đồng theo mẫu thực tế. Xác nhận phiên bản và chuyển tiếp tại mốc nghĩa vụ.','Chỉ kiểm tra nội dung bắt buộc của hợp đồng theo mẫu; quan hệ doanh nghiệp phục vụ thương mại không tự thuộc phạm vi. Thành phần liên hệ khác chỉ khi có; cấu thành giá khi luật yêu cầu. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07 00:00:00+00:00'::timestamptz,'AI_DOI_CHIEU_NGUON_CHINH_THUC_CHUA_DUYET',true,'NOI_DUNG_HOP_DONG_THEO_MAU','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
