INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC062_01','PV_GYC062',1,'Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc.','PERFORMANCE_WITH_DOCUMENTS','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_GYC062","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_25','29/2023/QH15; Điều 25 khoản 1','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','Nhánh thương mại: mua bán căn hộ hình thành trong tương lai, không phải thuê mua, không áp tự động cho NOXH/bán lại cá nhân. Xác minh mốc, giá trị hợp đồng, khoản đặt cọc và chuyển tiếp Điều 83 trước kết luận.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07 00:00:00+00:00'::timestamptz,'SOURCE_EXTRACTED_PENDING_HUMAN',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC064_01','PV_GYC064',1,'Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%.','PERFORMANCE_WITH_DOCUMENTS','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_GYC064","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_25','29/2023/QH15; Điều 25 khoản 1','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','Mua bán nhà ở/công trình hình thành trong tương lai thuộc Điều 25; không dùng checklist thuê mua cho mua bán; xác minh tiến độ, chủ thể bên bán, mốc và chuyển tiếp. Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07 00:00:00+00:00'::timestamptz,'SOURCE_EXTRACTED_PENDING_HUMAN',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
