g tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07 00:00:00+00:00'::timestamptz,'SOURCE_EXTRACTED_PENDING_HUMAN',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC104_01','PV_GYC104',1,'Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng.','CONTRACT_CONTENT','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":["EX_APT_MAINTENANCE_OLD"],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_GYC104","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Hồ sơ liên quan: mức 2% khi áp dụng, giá trị căn hộ/phần diện tích làm căn cứ, tách khoản bảo trì khỏi giá bán, trách nhiệm từng chủ sở hữu, tài khoản và chứng từ. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL007_152','27/2023/QH15; Điều 152 khoản 1','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','Cần xác minh phạm vi giao dịch, chủ thể, thời gian và điều khoản chuyển tiếp. Xác nhận loại nhà ở và giao dịch; nội dung giao dịch nhà ở thương mại của doanh nghiệp có chức năng BĐS phải route Luật KDBĐS theo khoản 2 Điều 1.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Hợp đồng trước 01/07/2006 hoặc giai đoạn 01/07/2006 đến trước luật mới phải đối chiếu khoản 3,4 Điều 152, không mặc định toàn bộ đều 2% người mua đóng.','2026-10-07 00:00:00+00:00'::timestamptz,'SOURCE_EXTRACTED_PENDING_HUMAN',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC154_01','PV_GYC154',1,'Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng.','CONTRACT_CONTENT','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":["EX_APT_WARRANTY_EQUIPMENT"],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_GYC154","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng. Hồ sơ liên quan: đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL007_129','27/2023/QH15; Điều 129 khoản 2 điểm a','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','Cần xác minh phạm vi giao dịch, chủ thể, thời gian và điều khoản chuyển tiếp. Xác nhận loại nhà ở và giao dịch; nội dung giao dịch nhà ở thương mại của doanh nghiệp có chức năng BĐS phải route Luật KDBĐS theo khoản 2 Điều 1.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Thiết bị có thời hạn nhà sản xuất; bán lại không tự khởi động lại bảo hành nhà chung cư 60 tháng.','2026-10-07 00:00:00+00:00'::timestamptz,'SOURCE_EXTRACTED_PENDING_HUMAN',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
