INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_APT_COMMERCIAL_CONTENT_WARRANTY','PV_APT_COMMERCIAL_CONTENT_2024',7,'Nội dung bảo hành trong đúng scope.','CONTRACT_CONTENT','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":["EX_APT_WARRANTY_EQUIPMENT"],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_APT_COMMERCIAL_CONTENT_2024","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Nội dung bảo hành trong đúng scope. Hồ sơ liên quan: đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_46','29/2023/QH15; Điều 46 khoản 1 điểm g','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','COMMERCIAL Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Thiết bị có thời hạn nhà sản xuất; bán lại không tự khởi động lại bảo hành nhà chung cư 60 tháng.','2026-10-07 00:00:00+00:00'::timestamptz,'SOURCE_EXTRACTED_PENDING_HUMAN',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_requi