_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC018_01','PV_HYC018',1,'Hợp đồng phải ghi tên của bên bán và bên mua.','NOI_DUNG_BAT_BUOC','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC018","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể, trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_18','66/2014/QH13; Điều 18 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ chung cư/nhà ở thương mại của doanh nghiệp kinh doanh BĐS, HĐ xác lập trong [2015-07-01, 2024-08-01) theo Luật KDBDS 66/2014 (luật chính; Luật Nhà ở 65/2014 bổ trợ theo Điều 1 Luật Nhà ở 2014). Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN, không tự áp Luật 29/2023.','Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Điều 18 chỉ liệt kê nội dung chính phải có, không quy định chi tiết từng nội dung; mức độ chi tiết tối thiểu đối chiếu thêm Luật Nhà ở 2014 (Đợt 2) và BVQLNTD 2010 (Đợt 3), không suy diễn ở tiêu chí này. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC018_02','PV_HYC018',2,'Hợp đồng phải ghi địa chỉ của bên bán và bên mua.','NOI_DUNG_BAT_BUOC','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC018","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng phải ghi địa chỉ của bên bán và bên mua. Hồ sơ liên quan: địa chỉ trụ sở bên bán, địa chỉ thường trú/liên hệ bên mua tại phần chủ thể. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_18','66/2014/QH13; Điều 18 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ chung cư/nhà ở thương mại của doanh nghiệp kinh doanh BĐS, HĐ xác lập trong [2015-07-01, 2024-08-01) theo Luật KDBDS 66/2014 (luật chính; Luật Nhà ở 65/2014 bổ trợ theo Điều 1 Luật Nhà ở 2014). Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN, không tự áp Luật 29/2023.','Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Điều 18 chỉ liệt kê nội dung chính phải có, không quy định chi tiết từng nội dung; mức độ chi tiết tối thiểu đối chiếu thêm Luật Nhà ở 2014 (Đợt 2) và BVQLNTD 2010 (Đợt 3), không suy diễn ở tiêu chí này. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC019_01','PV_HYC019',1,'Hợp đồng phải có thông tin xác định được căn hộ là đối tượng mua bán (ký hiệu/số căn, tầng, tòa/khối, dự án, địa chỉ hoặc vị trí).','NOI_DUNG_BAT_BUOC','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC019","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng phải có thông tin xác định được căn hộ là đối tượng mua bán (ký hiệu/số căn, tầng, tòa/khối, dự án, địa chỉ hoặc vị trí). Hồ sơ liên quan: mã/số căn hộ, tầng và tòa nhà, tên dự án/địa chỉ khu đất, phụ lục mô tả căn hộ, bản vẽ vị trí. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_18','66/2014/QH13; Điều 18 khoản 2','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ chung cư/nhà ở thương mại của doanh nghiệp kinh doanh BĐS, HĐ xác lập trong [2015-07-01, 2024-08-01) theo Luật KDBDS 66/2014 (luật chính; Luật Nhà ở 65/2014 bổ trợ theo Điều 1 Luật Nhà ở 2014). Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN, không tự áp Luật 29/2023.','[CAN_CHUYEN_GIA] Điều 18 khoản 2 chỉ ghi ''các thông tin về bất động sản''; tập yếu tố tối thiểu để ''xác định được'' là diễn giải – cần chuyên gia; VIOLATED về quyền đổi căn cũng cần xác nhận. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Điều 18 chỉ liệt kê nội dung chính phải có, không quy định chi tiết từng nội dung; mức độ chi tiết tối thiểu đối chiếu thêm Luật Nhà ở 2014 (Đợt 2) và BVQLNTD 2010 (Đợt 3), không suy diễn ở tiêu chí này. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC019_02','PV_HYC019',2,'Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích).','CONTRACT_CONTENT','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC019","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích). Hồ sơ liên quan: diện tích căn hộ, loại diện tích (sàn/sử dụng), phụ lục mô tả đặc điểm, trang thiết bị nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_18','66/2014/QH13; Điều 18 khoản 2','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ chung cư/nhà ở thương mại của doanh nghiệp kinh doanh BĐS, HĐ xác lập trong [2015-07-01, 2024-08-01) theo Luật KDBDS 66/2014 (luật chính; Luật Nhà ở 65/2014 bổ trợ theo Điều 1 Luật Nhà ở 2014). Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN, không tự áp Luật 29/2023.','[CAN_CHUYEN_GIA] Coi diện tích là ''thông tin về BĐS'' tối thiểu là diễn giải từ khoản 2; cần chuyên gia xác nhận có giữ tiêu chí này ở cấp Điều 18 hay chỉ để Luật Nhà ở 2014 Điều 121. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Điều 18 chỉ liệt kê nội dung chính phải có, không quy định chi tiết từng nội dung; mức độ chi tiết tối thiểu đối chiếu thêm Luật Nhà ở 2014 (Đợt 2) và BVQLNTD 2010 (Đợt 3), không suy diễn ở tiêu chí này. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC034_01','PV_HYC034',1,'Lần thanh toán đầu tiên đối với căn hộ hình thành trong tương lai không quá 30% giá trị hợp đồng.','PERFORMANCE_WITH_DOCUMENTS','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC034","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Lần thanh toán đầu tiên đối với căn hộ hình thành trong tương lai không quá 30% giá trị hợp đồng. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, số tiền/tỷ lệ đợt 1 trong lịch thanh toán, khoản đặt cọc/giữ chỗ trước ký, chứng từ đã thu. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_57','66/2014/QH13; Điều 57 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ HÌNH THÀNH TRONG TƯƠNG LAI (Điều 57 Luật 66/2014), HĐ xác lập trong [2015-07-01, 2024-08-01); không áp tự động cho NOXH, thuê mua, bán lại cá nhân hoặc căn hộ đã có. tinh_trang_tai_san chưa xác minh => UNKNOWN.','[CAN_CHUYEN_GIA] Đặt cọc/giữ chỗ trước ký có tính vào ''lần đầu'' theo Luật 66/2014 không; mẫu số ''giá trị hợp đồng'' gồm VAT/kinh phí bảo trì không – cần chuyên gia. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Luật 66/2014 không nói rõ đặt cọc có tính vào lần đầu; quy tắc ''bao gồm đặt cọc'' của Luật 29/2023 KHÔNG áp hồi tố. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC036_01','PV_HYC036',1,'Tổng số tiền thu trước khi bàn giao căn hộ hình thành trong tương lai không quá 70% giá trị hợp đồng; nếu bên bán là doanh nghiệp có vốn đầu tư nước ngoài thì không quá 50%.','PERFORMANCE_WITH_DOCUMENTS','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC036","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Tổng số tiền thu trước khi bàn giao căn hộ hình thành trong tương lai không quá 70% giá trị hợp đồng; nếu bên bán là doanh nghiệp có vốn đầu tư nước ngoài thì không quá 50%. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, tổng các đợt đến trước mốc bàn giao, mốc bàn giao trong lịch thanh toán, tư cách bên bán có vốn đầu tư nước ngoài (ben_ban_co_von_nuoc_ngoai) và bằng chứng, chứng từ đã thu. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_57','66/2014/QH13; Điều 57 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ HÌNH THÀNH TRONG TƯƠNG LAI (Điều 57 Luật 66/2014), HĐ xác lập trong [2015-07-01, 2024-08-01); không áp tự động cho NOXH, thuê mua, bán lại cá nhân hoặc căn hộ đã có. tinh_trang_tai_san chưa xác minh => UNKNOWN.','[CAN_CHUYEN_GIA] Định nghĩa ''doanh nghiệp có vốn đầu tư nước ngoài'' tại thời điểm 2015–2024 (mọi tỷ lệ vốn ngoại hay ngưỡng nhất định) và mẫu số ''giá trị hợp đồng'' – cần chuyên gia. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC037_01','PV_HYC037',1,'Khi bên mua chưa được cấp Giấy chứng nhận, tổng số tiền bên bán thu không quá 95% giá trị hợp đồng.','PERFORMANCE_WITH_DOCUMENTS','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC037","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Khi bên mua chưa được cấp Giấy chứng nhận, tổng số tiền bên bán thu không quá 95% giá trị hợp đồng. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, tổng các đợt đến trước mốc cấp Giấy chứng nhận, mọi ngoại lệ/điều khoản thanh toán sớm, chứng từ đã thu, tình trạng cấp Giấy chứng nhận. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_57','66/2014/QH13; Điều 57 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ HÌNH THÀNH TRONG TƯƠNG LAI (Điều 57 Luật 66/2014), HĐ xác lập trong [2015-07-01, 2024-08-01); không áp tự động cho NOXH, thuê mua, bán lại cá nhân hoặc căn hộ đã có. tinh_trang_tai_san chưa xác minh => UNKNOWN.','Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC037_02','PV_HYC037',2,'Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua.','CONTRACT_CONTENT','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC037","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua. Hồ sơ liên quan: điều khoản đợt thanh toán cuối, sự kiện kích hoạt đợt cuối, ngoại lệ (bên mua tự làm thủ tục, chậm nộp hồ sơ), phụ lục thanh toán. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL010_57','66/2014/QH13; Điều 57 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46749','Mua bán căn hộ HÌNH THÀNH TRONG TƯƠNG LAI (Điều 57 Luật 66/2014), HĐ xác lập trong [2015-07-01, 2024-08-01); không áp tự động cho NOXH, thuê mua, bán lại cá nhân hoặc căn hộ đã có. tinh_trang_tai_san chưa xác minh => UNKNOWN.','[CAN_CHUYEN_GIA] Các mốc lai như ''khi bên bán bàn giao GCN'', ''khi có thông báo đã có GCN'', hoặc ngoại lệ do bên mua chậm hồ sơ có hợp lệ không – cần chuyên gia. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Không mượn tiêu chí/ngưỡng của Luật 29/2023 hoặc Mẫu NĐ 96/2024 cho phiên bản này; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONTRACT_TEXT','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC039_01','PV_HYC039',1,'Hợp đồng phải ghi họ và tên (cá nhân) hoặc tên tổ chức của các bên.','NOI_DUNG_BAT_BUOC','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC039","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng phải ghi họ và tên (cá nhân) hoặc tên tổ chức của các bên. Hồ sơ liên quan: họ tên bên mua cá nhân, tên doanh nghiệp/tổ chức bên bán tại phần chủ thể và trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','DKPL0228','65/2014/QH13; Điều 121 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Áp dụng trực tiếp cho giao dịch ngoài KDBDS (bán lại cá nhân); với giao dịch KDBDS chỉ bổ trợ nội dung Điều 18 Luật 66/2014 không quy định. Nội dung trùng Điều 18 Luật 66/2014: khi bên bán là doanh nghiệp KDBDS, không tính hai lần trong tổng hợp.','[CAN_CHUYEN_GIA] Hai version KDBDS và NHAO cùng family, cùng khoảng hiệu lực, che_do_ket_hop không loại trừ nguồn đồng thời => một lỗi bị tính hai lần. Cần chuyên gia quyết định version NHAO có NOT_APPLICABLE khi bên bán là doanh nghiệp KDBDS (Điều 1 Luật Nhà ở 2014) hay không. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Trùng nội dung TC_PV_HYC018_01 (KDBDS 2014). Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC039_02','PV_HYC039',2,'Hợp đồng phải ghi địa chỉ của các bên.','NOI_DUNG_BAT_BUOC','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC039","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng phải ghi địa chỉ của các bên. Hồ sơ liên quan: địa chỉ trụ sở tổ chức, địa chỉ cá nhân tại phần chủ thể. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','DKPL0228','65/2014/QH13; Điều 121 khoản 1','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Áp dụng trực tiếp cho giao dịch ngoài KDBDS (bán lại cá nhân); với giao dịch KDBDS chỉ bổ trợ nội dung Điều 18 Luật 66/2014 không quy định. Nội dung trùng Điều 18 Luật 66/2014: khi bên bán là doanh nghiệp KDBDS, không tính hai lần trong tổng hợp.','[CAN_CHUYEN_GIA] Hai version KDBDS và NHAO cùng family, cùng khoảng hiệu lực, che_do_ket_hop không loại trừ nguồn đồng thời => một lỗi bị tính hai lần. Cần chuyên gia quyết định version NHAO có NOT_APPLICABLE khi bên bán là doanh nghiệp KDBDS (Điều 1 Luật Nhà ở 2014) hay không. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Trùng nội dung TC_PV_HYC018_02 (KDBDS 2014). Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC049_01','PV_HYC049',1,'Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung.','CONTRACT_CONTENT','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC049","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung. Hồ sơ liên quan: điều khoản kinh phí bảo trì, số tiền/tỷ lệ, căn cứ tính, thời điểm nộp, tài khoản nhận, phụ lục giá. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL011_108','65/2014/QH13; Điều 108 khoản 1 điểm a','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Nhà chung cư có nhiều chủ sở hữu, căn hộ do CHỦ ĐẦU TƯ bán (ben_ban_la_chu_dau_tu); không áp cho bán lại cá nhân.','[CAN_CHUYEN_GIA] Mức ''quy định rõ'' (chỉ ghi ''2% theo luật'' có đủ không) cần chuyên gia. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Nhà chung cư hỗn hợp có tách khu chức năng: xét khoản 5 Điều 108 về phân chia kinh phí. Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',true,'CONTRACT_TEXT','{"MISSING":"ADD_MANDATORY_CONTENT","SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC049_02','PV_HYC049',2,'Kinh phí bảo trì phần sở hữu chung ghi trong hợp đồng bằng 2% giá trị căn hộ bán.','DOI_CHIEU_CO_DIEU_KIEN','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC049","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Kinh phí bảo trì phần sở hữu chung ghi trong hợp đồng bằng 2% giá trị căn hộ bán. Hồ sơ liên quan: giá trị căn hộ làm căn cứ tính, tỷ lệ/số tiền kinh phí bảo trì ghi trong HĐ, thuế/khoản bao gồm. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL011_108','65/2014/QH13; Điều 108 khoản 1 điểm a','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Nhà chung cư có nhiều chủ sở hữu, căn hộ do CHỦ ĐẦU TƯ bán (ben_ban_la_chu_dau_tu); không áp cho bán lại cá nhân.','[CAN_CHUYEN_GIA] Mẫu số ''giá trị căn hộ'' (trước/sau VAT, gồm hay không chính kinh phí bảo trì) không có trong Điều 108 – cần chuyên gia chốt. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Điều 108 không định nghĩa ''giá trị căn hộ''; không mượn định nghĩa của NĐ 99/2015 hay luật mới khi chưa được duyệt. Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONTRACT_TEXT','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC049_03','PV_HYC049',3,'Kinh phí bảo trì được tính vào tiền bán mà bên mua đóng khi nhận bàn giao căn hộ.','DOI_CHIEU_CO_DIEU_KIEN','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC049","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Kinh phí bảo trì được tính vào tiền bán mà bên mua đóng khi nhận bàn giao căn hộ. Hồ sơ liên quan: thời điểm/đợt nộp kinh phí bảo trì trong lịch thanh toán, mốc bàn giao, điều khoản kinh phí bảo trì. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL011_108','65/2014/QH13; Điều 108 khoản 1 điểm a','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Nhà chung cư có nhiều chủ sở hữu, căn hộ do CHỦ ĐẦU TƯ bán (ben_ban_la_chu_dau_tu); không áp cho bán lại cá nhân.','[CAN_CHUYEN_GIA] ''Tính vào tiền bán… phải đóng khi nhận bàn giao'' – thu sớm hơn bàn giao có là VIOLATED hay chỉ là thỏa thuận thời điểm, cần chuyên gia. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONTRACT_TEXT','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC053_01','PV_HYC053',1,'Thời hạn bảo hành nhà chung cư ghi trong hợp đồng tối thiểu 60 tháng.','DOI_CHIEU_CO_DIEU_KIEN','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC053","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Thời hạn bảo hành nhà chung cư ghi trong hợp đồng tối thiểu 60 tháng. Hồ sơ liên quan: thời hạn bảo hành ghi trong HĐ, đơn vị (tháng/năm), hạng mục áp dụng, tình trạng nhà xây mới. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL011_85','65/2014/QH13; Điều 85 khoản 2 điểm a','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Nhà ở đầu tư xây dựng để bán (chủ đầu tư/bên bán nhà xây mới); Điều 20 khoản 2 Luật 66/2014 dẫn chiếu thời hạn bảo hành theo pháp luật nhà ở. Không áp cho bán lại căn hộ đã qua sử dụng.','Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Điều 182 khoản 4 (HĐ ký trước 01/07/2015) nằm ngoài khoảng hiệu lực version này. Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONTRACT_TEXT','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","dieu_kien","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_HYC053_02','PV_HYC053',2,'Mốc bắt đầu tính thời hạn bảo hành không sớm hơn thời điểm hoàn thành xây dựng và nghiệm thu đưa nhà ở vào sử dụng.','DOI_CHIEU_CO_DIEU_KIEN','{"case_facts_required":true,"criterion_target_only":true,"exception_ids":[],"local_applicability_only":true,"not_selected_policy":null,"optional_choice":false,"requirement_version_id":"PV_HYC053","scope_missing_policy":"UNKNOWN"}','Chỉ kiểm tra Mốc bắt đầu tính thời hạn bảo hành không sớm hơn thời điểm hoàn thành xây dựng và nghiệm thu đưa nhà ở vào sử dụng. Hồ sơ liên quan: mốc bắt đầu bảo hành ghi trong HĐ (nghiệm thu, bàn giao căn hộ, ngày cố định), ngày nghiệm thu nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_DRAFT_PENDING_HUMAN',false,true,'AI_DRAFT_PENDING_HUMAN','ART_VBPL011_85','65/2014/QH13; Điều 85 khoản 2 điểm a','https://vbpl.vn/TW/Pages/vbpq-thuoctinh.aspx?ItemID=46742','Hợp đồng mua bán căn hộ chung cư xác lập trong [2015-07-01, 2024-08-01) theo Luật Nhà ở 65/2014. Theo Điều 1 Luật Nhà ở 2014, mua bán nhà ở thương mại của doanh nghiệp KDBDS thực hiện theo pháp luật KDBDS: Luật 66/2014 là luật chính, Điều này bổ trợ. Mốc xác lập ngoài khoảng hoặc chưa xác minh => UNKNOWN. Nhà ở đầu tư xây dựng để bán (chủ đầu tư/bên bán nhà xây mới); Điều 20 khoản 2 Luật 66/2014 dẫn chiếu thời hạn bảo hành theo pháp luật nhà ở. Không áp cho bán lại căn hộ đã qua sử dụng.','[CAN_CHUYEN_GIA] Mốc ''kể từ ngày bàn giao'' muộn hơn nghiệm thu – coi là SATISFIED (có lợi cho bên mua) cần chuyên gia xác nhận. Phân biệt nghĩa vụ phải có nội dung và nghĩa vụ thực hiện; không áp máy móc cho NOXH/bán lại cá nhân. Không mượn tiêu chí/ngưỡng của Luật Nhà ở 2023, Luật KDBDS 2023 hoặc Mẫu NĐ 96/2024; dữ kiện chưa rõ là UNKNOWN.','2026-10-11 00:00:00+00:00'::timestamptz,'AI_TRICH_FILE_NGUOI_DUNG_CHUA_DUYET',false,'CONTRACT_TEXT','{"MISSING":null,"SATISFIED":null,"UNKNOWN":"REQUEST_EVIDENCE","VIOLATED":"AMEND_OR_CORRECT_PROVEN_BREACH","scope_and_version_required":true,"source_required":true}') ON CONFLICT ("tieu_chi_id") DO NOTHING;
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_01_UNKNOWN','TC_PV_GYC005_01','UNKNOWN','{"criterion_target_only":true,"enabled":true,"gate":{"any_unresolved_fact":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có.',100,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007') ON CONFLICT ("quy_tac_id") DO NOTHING;
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_01_VIOLATED','TC_PV_GYC005_01','VIOLATED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Tên bên bán và bên mua xác định được. Tên/chủ thể hoặc người ký trong hợp đồng trái hồ sơ định danh/ủy quyền hợp lệ đã đối chiếu; không suy vi phạm chỉ từ tên viết tắt hoặc chỗ trống của mẫu.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Tên bên bán và bên mua xác định được. Tên/chủ thể hoặc người ký trong hợp đồng trái hồ sơ định danh/ủy quyền hợp lệ đã đối chiếu; không suy vi phạm chỉ từ tên viết tắt hoặc chỗ trống của mẫu.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007') ON CONFLICT ("quy_tac_id") DO NOTHING;
