INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_APT_COMMERCIAL_CONTENT_METHOD_VIOLATED','TC_APT_COMMERCIAL_CONTENT_METHOD','VIOLATED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Phương thức thanh toán xác định được. Phương thức được quy định trái nghĩa vụ thanh toán qua tài khoản trong scope Điều 48, hoặc thông tin người nhận đã chứng minh không hợp lệ.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Phương thức thanh toán xác định được. Phương thức được quy định trái nghĩa vụ thanh toán qua tài khoản trong scope Điều 48, hoặc thông tin người nhận đã chứng minh không hợp lệ.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007') ON CONFLICT ("quy_tac_id") DO NOTHING;
