INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_APT_COMMERCIAL_CONTENT_METHOD_SATISFIED','TC_APT_COMMERCIAL_CONTENT_METHOD','SATISFIED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận SATISFIED cho mệnh đề: Phương thức thanh toán xác định được. Phương thức thanh toán đủ xác định. Nếu thanh toán cho chủ đầu tư/doanh nghiệp kinh doanh bất động sản thuộc Điều 48 thì phải đối chiếu yêu cầu qua tài khoản. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận SATISFIED cho mệnh đề: Phương thức thanh toán xác định được. Phương thức thanh toán đủ xác định. Nếu thanh toán cho chủ đầu tư/doanh nghiệp kinh doanh bất động sản thuộc Điều 48 thì phải đối chiếu yêu cầu qua tài khoản. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007') ON CONFLICT ("quy_tac_id") DO NOTHING;
