INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_APT_COMMERCIAL_CONTENT_HANDOVER_SATISFIED','TC_APT_COMMERCIAL_CONTENT_HANDOVER','SATISFIED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận SATISFIED cho mệnh đề: Thời hạn giao nhận căn hộ và hồ sơ kèm theo. Cam kết thời gian, điều kiện và thủ tục xác định được. Khi kiểm tra thực hiện, phải có hồ sơ nghiệm thu/hạ tầng, thông báo và biên bản, không dùng cam kết làm chứng cứ đã bàn giao. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận SATISFIED cho mệnh đề: Thời hạn giao nhận căn hộ và hồ sơ kèm theo. Cam kết thời gian, điều kiện và thủ tục xác định được. Khi kiểm tra thực hiện, phải có hồ sơ nghiệm thu/hạ tầng, thông báo và biên bản, không dùng cam kết làm chứng cứ đã bàn giao. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007') ON CONFLICT ("quy_tac_id") DO NOTHING;
