INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_HYC034_01_SATISFIED','TC_PV_HYC034_01','SATISFIED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":{"denominator":"contract_price","deposit_inclusion":"EXPERT_REVIEW_REQUIRED","first_payment_lte_ratio":0.3,"scope":"FUTURE_FORMED_KDBDS_2014"},"predicate":"Chỉ kết luận SATISFIED cho mệnh đề: Lần thanh toán đầu tiên đối với căn hộ hình thành trong tương lai không quá 30% giá trị hợp đồng. Tiền đợt 1 / giá trị hợp đồng <= 0,30 theo lịch thanh toán (và chứng từ nếu có); mẫu số xác định được. Nếu có đặt cọc/giữ chỗ riêng và tổng đợt 1 + cọc > 30% thì UNKNOWN chờ chuyên gia, không tự SATISFIED. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận SATISFIED cho mệnh đề: Lần thanh toán đầu tiên đối với căn hộ hình thành trong tương lai không quá 30% giá trị hợp đồng. Tiền đợt 1 / giá trị hợp đồng <= 0,30 theo lịch thanh toán (và chứng từ nếu có); mẫu số xác định được. Nếu có đặt cọc/giữ chỗ riêng và tổng đợt 1 + cọc > 30% thì UNKNOWN chờ chuyên gia, không tự SATISFIED. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_DRAFT_PENDING_HUMAN',false,'HIST_CRITERIA_DRAFT_20261011') ON CONFLICT ("quy_tac_id") DO NOTHING;
