INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_HYC037_01_SATISFIED','TC_PV_HYC037_01','SATISFIED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":{"before_certificate_cumulative_lte_ratio":0.95,"denominator":"contract_price","scope":"FUTURE_FORMED_KDBDS_2014"},"predicate":"Chỉ kết luận SATISFIED cho mệnh đề: Khi bên mua chưa được cấp Giấy chứng nhận, tổng số tiền bên bán thu không quá 95% giá trị hợp đồng. Tổng các đợt phải trả trước khi cơ quan có thẩm quyền cấp Giấy chứng nhận / giá trị hợp đồng <= 0,95, xét cả ngoại lệ và phụ lục. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận SATISFIED cho mệnh đề: Khi bên mua chưa được cấp Giấy chứng nhận, tổng số tiền bên bán thu không quá 95% giá trị hợp đồng. Tổng các đợt phải trả trước khi cơ quan có thẩm quyền cấp Giấy chứng nhận / giá trị hợp đồng <= 0,95, xét cả ngoại lệ và phụ lục. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_DRAFT_PENDING_HUMAN',false,'HIST_CRITERIA_DRAFT_20261011') ON CONFLICT ("quy_tac_id") DO NOTHING;
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_HYC037_02_UNKNOWN','TC_PV_HYC037_02','UNKNOWN','{"criterion_target_only":true,"enabled":true,"gate":{"any_unresolved_fact":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: điều khoản đợt thanh toán cuối, sự kiện kích hoạt đợt cuối, ngoại lệ (bên mua tự làm thủ tục, chậm nộp hồ sơ), phụ lục thanh toán. Mốc ''khi bàn giao Giấy chứng nhận'' hoặc ngoại lệ do lỗi bên mua chậm hồ sơ => UNKNOWN + chuyển chuyên gia.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: điều khoản đợt thanh toán cuối, sự kiện kích hoạt đợt cuối, ngoại lệ (bên mua tự làm thủ tục, chậm nộp hồ sơ), phụ lục thanh toán. Mốc ''khi bàn giao Giấy chứng nhận'' hoặc ngoại lệ do lỗi bên mua chậm hồ sơ => UNKNOWN + chuyển chuyên gia.',100,'AI_DRAFT_PENDING_HUMAN',false,'HIST_CRITERIA_DRAFT_20261011') ON CONFLICT ("quy_tac_id") DO NOTHING;
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_HYC037_02_VIOLATED','TC_PV_HYC037_02','VIOLATED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua. Đợt cuối kích hoạt bởi sự kiện sớm hơn việc cấp Giấy chứng nhận (bàn giao căn hộ, nộp hồ sơ, ''đủ điều kiện cấp'', thông báo của bên bán) mà không chờ cấp GCN.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua. Đợt cuối kích hoạt bởi sự kiện sớm hơn việc cấp Giấy chứng nhận (bàn giao căn hộ, nộp hồ sơ, ''đủ điều kiện cấp'', thông báo của bên bán) mà không chờ cấp GCN.',80,'AI_DRAFT_PENDING_HUMAN',false,'HIST_CRITERIA_DRAFT_20261011') ON CONFLICT ("quy_tac_id") DO NOTHING;
