INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_HYC053_02_VIOLATED','TC_PV_HYC053_02','VIOLATED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Mốc bắt đầu tính thời hạn bảo hành không sớm hơn thời điểm hoàn thành xây dựng và nghiệm thu đưa nhà ở vào sử dụng. Mốc bắt đầu sớm hơn nghiệm thu đưa vào sử dụng (ví dụ ngày ký HĐ, ngày cất nóc, ngày cố định trước nghiệm thu), làm rút ngắn thời gian bảo hành thực tế.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Mốc bắt đầu tính thời hạn bảo hành không sớm hơn thời điểm hoàn thành xây dựng và nghiệm thu đưa nhà ở vào sử dụng. Mốc bắt đầu sớm hơn nghiệm thu đưa vào sử dụng (ví dụ ngày ký HĐ, ngày cất nóc, ngày cố định trước nghiệm thu), làm rút ngắn thời gian bảo hành thực tế.',80,'AI_DRAFT_PENDING_HUMAN',false,'HIST_CRITERIA_DRAFT_20261011') ON CONFLICT ("quy_tac_id") DO NOTHING;
