INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_HYC053_02_SATISFIED','TC_PV_HYC053_02','SATISFIED','{"criterion_target_only":true,"enabled":true,"gate":{"evidence_validated":true,"exceptions_resolved":true,"no_unresolved_conflict":true,"scope_confirmed":true,"source_available":true,"version_resolved":true},"human_approval_required_for_final":true,"numeric_rule":null,"predicate":"Chỉ kết luận SATISFIED cho mệnh đề: Mốc bắt đầu tính thời hạn bảo hành không sớm hơn thời điểm hoàn thành xây dựng và nghiệm thu đưa nhà ở vào sử dụng. Mốc bắt đầu là nghiệm thu đưa vào sử dụng hoặc mốc muộn hơn (ví dụ bàn giao căn hộ cho bên mua). Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.","scope_of_facts":"CURRENT_CRITERION","template_output":"DRAFT"}','Chỉ kết luận SATISFIED cho mệnh đề: Mốc bắt đầu tính thời hạn bảo hành không sớm hơn thời điểm hoàn thành xây dựng và nghiệm thu đưa nhà ở vào sử dụng. Mốc bắt đầu là nghiệm thu đưa vào sử dụng hoặc mốc muộn hơn (ví dụ bàn giao căn hộ cho bên mua). Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_DRAFT_PENDING_HUMAN',false,'HIST_CRITERIA_DRAFT_20261011') ON CONFLICT ("quy_tac_id") DO NOTHING;
INSERT INTO "knowledge"."quy_tac_tong_hop" ("quy_tac_tong_hop_id","rule_version","dieu_kien_json","thu_tu_uu_tien_json","trang_thai") VALUES ('AGG_CAN_HO_V1','CAN_HO_SEED_RULES_20261007','{"COMPLIANT":"all applicable mandatory criteria SATISFIED and no unresolved scope/version/evidence","INSUFFICIENT":"scope/version unresolved OR no applicable evaluated criterion OR any remaining UNKNOWN without already-proven violation","NON_COMPLIANT":"any applicable mandatory criterion VIOLATED; or all applicable mandatory criteria MISSING with verified absence","PARTIAL":"at least one SATISFIED and at least one verified MISSING; no VIOLATED/UNKNOWN","excluded":"NOT_APPLICABLE excluded with reason; REVIEW_REQUIRED is not a criterion finding"}','["SCOPE_OR_VERSION_UNRESOLVED=INSUFFICIENT","PROVEN_VIOLATION=NON_COMPLIANT_WITH_COVERAGE_FLAG","UNKNOWN=INSUFFICIENT","ALL_MISSING=NON_COMPLIANT","MIXED_SATISFIED_MISSING=PARTIAL","ALL_SATISFIED=COMPLIANT"]','ENGINE_POLICY') ON CONFLICT ("quy_tac_tong_hop_id") DO NOTHING;
