INSERT INTO "knowledge"."danh_muc_rui_ro" ("rui_ro_id","nhanh","risk_family","ten_rui_ro","muc_do_co_so","mo_ta","trang_thai_ra_soat","loai_du_lieu","trang_thai_nguon","tieu_chi_id","ban_chat_rui_ro") VALUES ('RR_TC_PV_GYC005_01_MISSING','COMPLIANCE','TC_PV_GYC005_01','Thiếu nội dung: Tên bên bán và bên mua xác định được.','HIGH','Có thể không xác định đúng người chịu nghĩa vụ hoặc phát sinh tranh chấp về đại diện. Chỉ phát sinh khi finding MISSING và gate của quy_tac_rui_ro đã đủ. Mức HIGH là ưu tiên xử lý nội bộ, không phải mức phạt hay kết luận vô hiệu.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_01','CONDITIONAL_COMPLIANCE') ON CONFLICT ("rui_ro_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_rui_ro" ("rui_ro_id","nhanh","risk_family","ten_rui_ro","muc_do_co_so","mo_ta","trang_thai_ra_soat","loai_du_lieu","trang_thai_nguon","tieu_chi_id","ban_chat_rui_ro") VALUES ('RR_TC_PV_GYC005_01_VIOLATED','COMPLIANCE','TC_PV_GYC005_01','Có dấu hiệu trái yêu cầu: Tên bên bán và bên mua xác định được.','HIGH','Có thể không xác định đúng người chịu nghĩa vụ hoặc phát sinh tranh chấp về đại diện. Chỉ phát sinh khi finding VIOLATED và gate của quy_tac_rui_ro đã đủ. Mức HIGH là ưu tiên xử lý nội bộ, không phải mức phạt hay kết luận vô hiệu.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_01','CONDITIONAL_COMPLIANCE') ON CONFLICT ("rui_ro_id") DO NOTHING;
