INSERT INTO "knowledge"."danh_muc_rui_ro" ("rui_ro_id","nhanh","risk_family","ten_rui_ro","muc_do_co_so","mo_ta","trang_thai_ra_soat","loai_du_lieu","trang_thai_nguon","tieu_chi_id","ban_chat_rui_ro") VALUES ('RR_CITATION_STALE','CITATION','CITATION_STALE','Viện dẫn không còn phù hợp tại mốc áp dụng','LOW','Viện dẫn không phù hợp tại mốc phải áp dụng đã xác minh; căn cứ lịch sử còn áp dụng theo chuyển tiếp không tự là stale. Có thể làm người đọc xác định sai căn cứ, không tự chứng minh nghĩa vụ hợp đồng vi phạm.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'CITATION_ONLY') ON CONFLICT ("rui_ro_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_rui_ro" ("rui_ro_id","nhanh","risk_family","ten_rui_ro","muc_do_co_so","mo_ta","trang_thai_ra_soat","loai_du_lieu","trang_thai_nguon","tieu_chi_id","ban_chat_rui_ro") VALUES ('RR_CITATION_INVALID','CITATION','CITATION_INVALID','Viện dẫn sai danh tính/số hiệu','LOW','Số hiệu, tên hoặc quan hệ văn bản không khớp nguồn chính thức đã xác minh. Sửa đúng danh tính được chứng minh; không suy rằng toàn bộ hợp đồng vô hiệu.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'CITATION_ONLY') ON CONFLICT ("rui_ro_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_rui_ro" ("rui_ro_id","nhanh","risk_family","ten_rui_ro","muc_do_co_so","mo_ta","trang_thai_ra_soat","loai_du_lieu","trang_thai_nguon","tieu_chi_id","ban_chat_rui_ro") VALUES ('RR_CITATION_UNKNOWN','CITATION','CITATION_UNKNOWN','Chưa xác minh được viện dẫn','REVIEW_REQUIRED','Chưa đủ dữ liệu nguồn, mốc hoặc định danh để xác minh viện dẫn. Giữ nguyên kết luận chưa xác định, không tự chọn văn bản thay thế.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'CITATION_ONLY') ON CONFLICT ("rui_ro_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_rui_ro" ("rui_ro_id","nhanh","risk_family","ten_rui_ro","muc_do_co_so","mo_ta","trang_thai_ra_soat","loai_du_lieu","trang_thai_nguon","tieu_chi_id","ban_chat_rui_ro") VALUES ('RR_CITATION_DOMAIN_MISMATCH','CITATION','DOMAIN_MISMATCH','Căn cứ viện dẫn không phù hợp vấn đề pháp lý','LOW','Văn bản có thể tồn tại và cùng lĩnh vực nhà ở nhưng Điều/Khoản được dùng không điều chỉnh vấn đề của giao dịch. Cần đối chiếu chủ thể, đối tượng và mục đích viện dẫn; không tự kết luận hợp đồng vô hiệu hoặc nghĩa vụ bị vi phạm.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'CITATION_ONLY') ON CONFLICT ("rui_ro_id") DO NOTHING;
