INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC005_01_MISSING','COMPLIANCE','MISSING','Điền tên theo hồ sơ định danh/đăng ký và bổ sung người đại diện, căn cứ ủy quyền khi áp dụng. Mục tiêu chỉ là tiêu chí TC_PV_GYC005_01: Tên bên bán và bên mua xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Bên bán: [tên theo hồ sơ], do [người có thẩm quyền] đại diện [nếu áp dụng]. Bên mua: [tên theo hồ sơ], do [người có thẩm quyền] đại diện [nếu áp dụng].','Kiểm tra lại TC_PV_GYC005_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu tên, mã định danh phù hợp và chữ ký/ủy quyền; không xác nhận giao dịch đã ký chỉ từ tên.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có','["Tên bên bán và bên mua xác định được.","tên đầy đủ bên bán","tên đầy đủ bên mua","tư cách người đại diện nếu có"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
