INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC006_01_MISSING','COMPLIANCE','MISSING','Chuẩn hóa mô tả căn hộ và kèm bản vẽ, phụ lục xác định đối tượng. Mục tiêu chỉ là tiêu chí TC_PV_GYC006_01: Có mô tả sản phẩm/hàng hóa/dịch vụ xác định được đối tượng giao dịch. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Căn hộ [mã], tầng [tầng], tòa [tòa], dự án [tên], tại [địa chỉ], theo bản vẽ/phụ lục [mã đã có].','Kiểm tra lại TC_PV_GYC006_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu xuyên suốt hợp đồng, bản vẽ, bảng giá và biên bản bàn giao nếu có.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC006_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. mã/số căn hộ, tầng và tòa nhà, dự án/địa chỉ, đặc điểm hoặc phụ lục mô tả','["Có mô tả sản phẩm/hàng hóa/dịch vụ xác định được đối tượng giao dịch.","mã/số căn hộ","tầng và tòa nhà","dự án/địa chỉ","đặc điểm hoặc phụ lục mô tả"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
