INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC064_01_VIOLATED','COMPLIANCE','VIOLATED','Điều chỉnh lịch thu về đúng ngưỡng và tiến độ; đối soát khoản đã thu vượt và xử lý hoàn trả/bù trừ bằng thỏa thuận hợp pháp. Mục tiêu chỉ là tiêu chí TC_PV_GYC064_01: Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Lần đầu, gồm đặt cọc: không quá 30% giá trị hợp đồng. Lũy kế trước bàn giao: không quá 70%, hoặc 50% khi bên bán thuộc diện khoản 4 Điều 10. Khi chưa được cấp Giấy chứng nhận: không quá 95%. Chỉ dùng trong scope Điều 25 đã xác nhận.','Kiểm tra lại TC_PV_GYC064_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Tính tỷ lệ từng mốc bằng số liệu và mẫu số thực; kiểm tra tiến độ xây dựng, ngoại lệ và luật theo thời điểm.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC064_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng','["Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%.","giá trị hợp đồng làm mẫu số","đặt cọc","lịch và khoản đã thu","tình trạng bàn giao/cấp giấy","tư cách vốn nước ngoài khi áp dụng"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
