INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC104_01_MISSING','COMPLIANCE','MISSING','Tách khoản bảo trì, ghi rõ căn cứ tính và trách nhiệm chủ sở hữu; đối soát chứng từ nộp, bàn giao và sử dụng. Mục tiêu chỉ là tiêu chí TC_PV_GYC104_01: Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Kinh phí bảo trì phần sở hữu chung: 2% giá trị căn hộ/phần diện tích thuộc diện áp dụng, tính riêng với giá bán. Chủ thể đóng, thời điểm nộp và tài khoản thực hiện theo Điều 152–153 và hồ sơ xác minh.','Kiểm tra lại TC_PV_GYC104_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối soát giá trị căn cứ, số tiền và khoản dành phần chủ đầu tư giữ lại; không tự lấy 2% mọi khoản thu hoặc mọi tài sản.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC104_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. mức 2% khi áp dụng, giá trị căn hộ/phần diện tích làm căn cứ, tách khoản bảo trì khỏi giá bán, trách nhiệm từng chủ sở hữu, tài khoản và chứng từ','["Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng.","mức 2% khi áp dụng","giá trị căn hộ/phần diện tích làm căn cứ","tách khoản bảo trì khỏi giá bán","trách nhiệm từng chủ sở hữu","tài khoản và chứng từ"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
