INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC104_01_UNKNOWN','COMPLIANCE','UNKNOWN','Yêu cầu hồ sơ để làm rõ đúng tiêu chí: Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Hồ sơ cần: mức 2% khi áp dụng, giá trị căn hộ/phần diện tích làm căn cứ, tách khoản bảo trì khỏi giá bán, trách nhiệm từng chủ sở hữu, tài khoản và chứng từ. Chưa sửa điều khoản hoặc kết luận vi phạm khi thiếu căn cứ.','Chưa đủ căn cứ đánh giá TC_PV_GYC104_01. Cần cung cấp [tài liệu còn thiếu thuộc tiêu chí] và xác nhận [mốc/ngoại lệ chưa rõ].','Kiểm tra lại TC_PV_GYC104_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối soát giá trị căn cứ, số tiền và khoản dành phần chủ đầu tư giữ lại; không tự lấy 2% mọi khoản thu hoặc mọi tài sản.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','REQUEST_VERIFICATION','REVIEW_REQUIRED','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC104_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. mức 2% khi áp dụng, giá trị căn hộ/phần diện tích làm căn cứ, tách khoản bảo trì khỏi giá bán, trách nhiệm từng chủ sở hữu, tài khoản và chứng từ','["Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng.","mức 2% khi áp dụng","giá trị căn hộ/phần diện tích làm căn cứ","tách khoản bảo trì khỏi giá bán","trách nhiệm từng chủ sở hữu","tài khoản và chứng từ"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC154_01_MISSING','COMPLIANCE','MISSING','Sửa thời hạn, mốc tính và phạm vi; xác định đầu mối tiếp nhận, hồ sơ nghiệm thu và cơ chế sửa chữa. Mục tiêu chỉ là tiêu chí TC_PV_GYC154_01: Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Nhà chung cư được bảo hành tối thiểu 60 tháng kể từ hoàn thành xây dựng và nghiệm thu đưa vào sử dụng, trong scope Điều 129. Thiết bị áp thời hạn nhà sản xuất. Đầu mối tiếp nhận: [thông tin xác minh].','Kiểm tra lại TC_PV_GYC154_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu ngày nghiệm thu, phạm vi nhà/thiết bị và hồ sơ yêu cầu, sửa chữa; không tự bắt đầu lại 60 tháng từ bán lại/bàn giao.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC154_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất','["Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng.","đối tượng/ phạm vi bảo hành","thời hạn","mốc hoàn thành và nghiệm thu","đầu mối và cách thông báo","bảo hành thiết bị theo nhà sản xuất"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
