INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_DEPOSIT_CAP_VIOLATED','COMPLIANCE','VIOLATED','Kiểm tra đủ điều kiện trước thu, ghi giá bán và điều chỉnh khoản đặt cọc; đối soát tiền đã nhận và phương án xử lý hợp pháp. Mục tiêu chỉ là tiêu chí TC_APT_DEPOSIT_CAP: Số tiền đặt cọc chủ đầu tư thu không quá 5% giá bán. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Giá bán dùng xác định đặt cọc: [giá có căn cứ]. Khoản đặt cọc: [số], không quá 5% khi khoản 5 Điều 23 áp dụng; chỉ thu sau khi căn hộ đủ điều kiện kinh doanh.','Kiểm tra lại TC_APT_DEPOSIT_CAP với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu thỏa thuận, chứng từ thu và hồ sơ đủ điều kiện tại ngày thu; không áp 5% cho mọi đặt cọc bán lại dân sự.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_DEPOSIT_CAP','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. giá bán được xác định trong thỏa thuận đặt cọc, số tiền đặt cọc, điều kiện đưa vào kinh doanh, thời điểm và người thu','["Số tiền đặt cọc chủ đầu tư thu không quá 5% giá bán.","giá bán được xác định trong thỏa thuận đặt cọc","số tiền đặt cọc","điều kiện đưa vào kinh doanh","thời điểm và người thu"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON C