INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_DEPOSIT_PRICE_UNKNOWN','COMPLIANCE','UNKNOWN','Yêu cầu hồ sơ để làm rõ đúng tiêu chí: Thỏa thuận đặt cọc ghi rõ giá bán căn hộ. Hồ sơ cần: giá bán được xác định trong thỏa thuận đặt cọc, số tiền đặt cọc, điều kiện đưa vào kinh doanh, thời điểm và người thu. Chưa sửa điều khoản hoặc kết luận vi phạm khi thiếu căn cứ.','Chưa đủ căn cứ đánh giá TC_APT_DEPOSIT_PRICE. Cần cung cấp [tài liệu còn thiếu thuộc tiêu chí] và xác nhận [mốc/ngoại lệ chưa rõ].','Kiểm tra lại TC_APT_DEPOSIT_PRICE với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu thỏa thuận, chứng từ thu và hồ sơ đủ điều kiện tại ngày thu; không áp 5% cho mọi đặt cọc bán lại dân sự.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','REQUEST_VERIFICATION','REVIEW_REQUIRED','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_DEPOSIT_PRICE','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. giá bán được xác định trong thỏa thuận đặt cọc, số tiền đặt cọc, điều kiện đưa vào kinh doanh, thời điểm và người thu','["Thỏa thuận đặt cọc ghi rõ giá bán căn hộ.","giá bán được xác định trong thỏa thuận đặt cọc","số tiền đặt cọc","điều kiện đưa vào kinh doanh","thời điểm và người thu"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
