INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_PRICE_MISSING','COMPLIANCE','MISSING','Đối soát giá, đơn giá, thuế và các khoản thu; tách kinh phí bảo trì khỏi giá bán. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_PRICE: Giá bán xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Giá bán: [giá xác minh], tính theo [căn cứ có trong hồ sơ]. Thuế: [quy định áp dụng]. Kinh phí bảo trì và khoản ngoài giá: [tách riêng, có căn cứ].','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_PRICE với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối soát bảng số, bằng chữ, diện tích và tổng các khoản; không tự đặt giá hoặc mức thuế.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_PRICE','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. giá bán hoặc cơ chế xác định giá, đơn giá/căn cứ diện tích khi áp dụng, thuế và khoản ngoài giá, kinh phí bảo trì tách riêng khi áp dụng','["Giá bán xác định được.","giá bán hoặc cơ chế xác định giá","đơn giá/căn cứ diện tích khi áp dụng","thuế và khoản ngoài giá","kinh phí bảo trì tách riêng khi áp dụng"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
