INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_METHOD_MISSING','COMPLIANCE','MISSING','Bổ sung phương thức phù hợp tư cách bên nhận và tài khoản được xác nhận nếu chuyển khoản. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_METHOD: Phương thức thanh toán xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Bên mua thanh toán bằng [phương thức hợp pháp được hai bên thống nhất]. Trường hợp chuyển khoản, người nhận và tài khoản [chỉ điền theo thông tin đã xác minh]. Đối chiếu Điều 48 nếu bên nhận thuộc diện bắt buộc qua tài khoản.','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_METHOD với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Kiểm tra người nhận, căn cứ tài khoản và nghĩa vụ chuyên ngành; không tự ghi ngân hàng hoặc số tài khoản.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','MEDIUM','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_METHOD','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. phương thức thanh toán, người nhận hoặc tài khoản khi phương thức cần xác định','["phương thức thanh toán đủ xác định","người nhận/tài khoản nếu phương thức và luật áp dụng yêu cầu"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
