INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_TERM_MISSING','COMPLIANCE','MISSING','Bổ sung mốc tính và số ngày; đối soát lịch thanh toán với tiến độ, bàn giao và cấp giấy. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_TERM: Thời hạn thanh toán xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Bên mua thanh toán [số tiền/đợt] trong [số và loại ngày] kể từ [sự kiện/ngày xác minh], theo điều kiện [đã thống nhất].','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_TERM với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Tính lại ngày đến hạn từ sự kiện thật; không suy chậm trả từ lịch cam kết khi chưa có chứng từ.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','MEDIUM','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_TERM','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. mốc/sự kiện đến hạn, số ngày và loại ngày, từng đợt thanh toán, số tiền/tỷ lệ mỗi đợt','["sự kiện hoặc ngày gốc","thời hạn và loại ngày","số tiền/đợt đến hạn"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
