INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_HANDOVER_MISSING','COMPLIANCE','MISSING','Làm rõ lịch, điều kiện và hồ sơ bàn giao; đối soát các mốc và xử lý chậm bàn giao theo thỏa thuận hợp pháp. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_HANDOVER: Thời hạn giao nhận căn hộ và hồ sơ kèm theo. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Bàn giao căn hộ trong [mốc có căn cứ] tại [địa điểm], sau khi đáp ứng [điều kiện pháp lý/thiết kế]. Lập biên bản ghi tình trạng, diện tích và hồ sơ kèm theo.','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_HANDOVER với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu thời hạn hợp lệ, tình trạng thực tế, thông báo, nghiệm thu và biên bản. Không ghi lùi ngày.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_HANDOVER','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. thời gian/sự kiện bàn giao, địa điểm và thủ tục, điều kiện nghiệm thu/hạ tầng, hồ sơ và biên bản bàn giao','["Thời hạn giao nhận căn hộ và hồ sơ kèm theo.","thời gian/sự kiện bàn giao","địa điểm và thủ tục","điều kiện nghiệm thu/hạ tầng","hồ sơ và biên bản bàn giao"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
