INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_WARRANTY_MISSING','COMPLIANCE','MISSING','Sửa thời hạn, mốc tính và phạm vi; xác định đầu mối tiếp nhận, hồ sơ nghiệm thu và cơ chế sửa chữa. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_WARRANTY: Nội dung bảo hành trong đúng scope. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Nhà chung cư được bảo hành tối thiểu 60 tháng kể từ hoàn thành xây dựng và nghiệm thu đưa vào sử dụng, trong scope Điều 129. Thiết bị áp thời hạn nhà sản xuất. Đầu mối tiếp nhận: [thông tin xác minh].','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_WARRANTY với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu ngày nghiệm thu, phạm vi nhà/thiết bị và hồ sơ yêu cầu, sửa chữa; không tự bắt đầu lại 60 tháng từ bán lại/bàn giao.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_WARRANTY','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất','["Nội dung bảo hành trong đúng scope.","đối tượng/ phạm vi bảo hành","thời hạn","mốc hoàn thành và nghiệm thu","đầu mối và cách thông báo","bảo hành thiết bị theo nhà sản xuất"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
