INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_RIGHTS_MISSING','COMPLIANCE','MISSING','Làm rõ nội dung và tham số thực sự cần thỏa thuận; giữ cơ chế mặc định hợp pháp hoặc lựa chọn phù hợp của các bên. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_RIGHTS: Quyền và nghĩa vụ các bên. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Các bên thống nhất [nội dung tiêu chí, điều kiện và tham số có căn cứ] trong phạm vi pháp luật cho phép. Khi không lựa chọn nội dung tùy chọn, áp quy định mặc định tương ứng nếu có.','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_RIGHTS với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Kiểm tra nội dung, điều kiện áp dụng, phụ lục và luật mặc định; không ép bổ sung mọi quyền/mệnh đề trong luật.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','MEDIUM','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_RIGHTS','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. nội dung điều khoản liên quan, điều kiện phát sinh, tham số được các bên chọn nếu có, giới hạn luật bắt buộc, phụ lục và cơ chế mặc định','["Quyền và nghĩa vụ các bên.","nội dung điều khoản liên quan","điều kiện phát sinh","tham số được các bên chọn nếu có","giới hạn luật bắt buộc","phụ lục và cơ chế mặc định"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
