INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_PENALTY_MISSING','COMPLIANCE','MISSING','Làm rõ cơ chế xử lý, thông báo, hoàn trả, phạt và bồi thường trên đúng căn cứ; các mức để bên có thẩm quyền thống nhất, không tự tạo. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_PENALTY: Nội dung phạt vi phạm được xác định hợp pháp; không tự gán mức phạt 8%. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Khi [hành vi/sự kiện được thỏa thuận hợp pháp], bên bị ảnh hưởng thông báo theo [thủ tục]. Chế tài tính trên [căn cứ], theo [mức hợp pháp đã thống nhất]. Hậu quả chấm dứt/hoàn trả thực hiện trong [thời hạn có căn cứ].','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_PENALTY với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Phân biệt phạt với lãi chậm trả/bồi thường; đối chiếu tính tự nguyện, nội dung bắt buộc, căn cứ tính và luật chuyên ngành.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_PENALTY','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. hành vi/sự kiện kích hoạt, mức/căn cứ tính nếu có, thông báo và thời hạn, hậu quả hoàn trả, quan hệ phạt/bồi thường','["Nội dung phạt vi phạm được xác định hợp pháp; không tự gán mức phạt 8%.","hành vi/sự kiện kích hoạt","mức/căn cứ tính nếu có","thông báo và thời hạn","hậu quả hoàn trả","quan hệ phạt/bồi thường"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
