INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_DISPUTE_MISSING','COMPLIANCE','MISSING','Sửa cơ chế giải quyết đúng thẩm quyền và quyền luật định; không bắt buộc trọng tài nếu chưa có lựa chọn hợp lệ. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_DISPUTE: Phương thức giải quyết tranh chấp. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Tranh chấp được giải quyết bằng [phương thức hợp pháp thống nhất]. Việc lựa chọn trọng tài nếu có phải đáp ứng điều kiện của pháp luật và quyền của người tiêu dùng; không loại trừ quyền luật định.','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_DISPUTE với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Kiểm tra thỏa thuận trọng tài riêng, phạm vi, thẩm quyền người ký, hình thức và quy định người tiêu dùng.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_DISPUTE','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. phương thức giải quyết, quyền khiếu nại/khởi kiện, thỏa thuận trọng tài nếu lựa chọn, phạm vi và hình thức thỏa thuận','["Phương thức giải quyết tranh chấp.","phương thức giải quyết","quyền khiếu nại/khởi kiện","thỏa thuận trọng tài nếu lựa chọn","phạm vi và hình thức thỏa thuận"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
