INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_APT_COMMERCIAL_CONTENT_EFFECT_MISSING','COMPLIANCE','MISSING','Hoàn thiện bản giao kết và hồ sơ chữ ký/đại diện, công chứng khi áp dụng; xác định mốc hiệu lực bằng căn cứ thật. Mục tiêu chỉ là tiêu chí TC_APT_COMMERCIAL_CONTENT_EFFECT: Thời điểm hiệu lực hợp đồng. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Hợp đồng được ký ngày [ngày có chứng cứ]. Hiệu lực từ [mốc hợp lệ theo thỏa thuận/pháp luật]. Người ký và chứng nhận: [theo hồ sơ, không ghi lùi ngày].','Kiểm tra lại TC_APT_COMMERCIAL_CONTENT_EFFECT với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu bản đầy đủ, chữ ký và hồ sơ công chứng/chứng thực hoặc giao kết điện tử; không bịa ngày ký.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_APT_COMMERCIAL_CONTENT_EFFECT','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. ngày tháng năm ký khi đã giao kết, chữ ký và tư cách người ký, thỏa thuận hiệu lực, công chứng/chứng thực khi bắt buộc','["Thời điểm hiệu lực hợp đồng.","ngày tháng năm ký khi đã giao kết","chữ ký và tư cách người ký","thỏa thuận hiệu lực","công chứng/chứng thực khi bắt buộc"]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
