INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_STALE','CITATION','STALE','Đối chiếu mốc đang đánh giá và quy định chuyển tiếp trước khi sửa viện dẫn. Nếu căn cứ đúng ở ngày giao kết thì giữ căn cứ lịch sử; chỉ đề xuất thay căn cứ không còn phù hợp vấn đề đang xét.','[DỰ THẢO] Căn cứ [nguyên văn] không còn phù hợp tại [mốc đã xác nhận]. Đề nghị xác minh [quy định chuyển tiếp] và điều chỉnh căn cứ cho đúng vấn đề của giao dịch; không thay tự động bằng văn bản hiện hành.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','CORRECT_REFERENCE','LOW','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.','["Viện dẫn nguyên văn và vị trí","Mã lý do và bằng chứng nguồn","Mốc và phạm vi đang đánh giá","Căn cứ chuyển tiếp/ngoại lệ nếu có","Hành động phù hợp trạng thái; thiếu gì yêu cầu đúng thứ đó"]','{"citation_does_not_drive_retrieval":true,"current_status_separate_from_historical":true,"human_review_required":true,"legal_basis_must_be_resolved":true,"no_auto_invalidity_or_fine":true,"no_auto_replace_old_law":true,"no_automatic_invalidity":true,"no_invented_replacement":true,"no_similarity_only_identity":true,"official_identity_and_temporal_evidence_required":true,"unknown_is_not_invalid":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_INVALID','CITATION','INVALID','Xác minh thành phần sai của số hiệu, loại văn bản, tên hoặc căn cứ được sử dụng; chỉ sửa theo nguồn chính thức xác định duy nhất. Không kết luận không tồn tại chỉ vì DB chưa có.','[DỰ THẢO] Đề nghị kiểm tra thành phần [sai lệch đã xác định] của viện dẫn [nguyên văn] với [nguồn chính thức], sau đó sửa đúng căn cứ; không lựa chọn văn bản chỉ vì tên tương tự.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','CORRECT_REFERENCE','LOW','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.','["Viện dẫn nguyên văn và vị trí","Mã lý do và bằng chứng nguồn","Mốc và phạm vi đang đánh giá","Căn cứ chuyển tiếp/ngoại lệ nếu có","Hành động phù hợp trạng thái; thiếu gì yêu cầu đúng thứ đó"]','{"citation_does_not_drive_retrieval":true,"current_status_separate_from_historical":true,"human_review_required":true,"legal_basis_must_be_resolved":true,"no_auto_invalidity_or_fine":true,"no_auto_replace_old_law":true,"no_automatic_invalidity":true,"no_invented_replacement":true,"no_similarity_only_identity":true,"official_identity_and_temporal_evidence_required":true,"unknown_is_not_invalid":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_UNKNOWN','CITATION','UNKNOWN','Yêu cầu bổ sung thông tin còn thiếu: bản nguồn, số hiệu/tên đầy đủ, vị trí trích dẫn, mốc đánh giá hoặc ngữ cảnh. Giữ UNKNOWN cho đến khi xác minh; không khẳng định viện dẫn sai.','[DỰ THẢO] Chưa đủ dữ liệu xác minh [nguyên văn]. Đề nghị cung cấp [thông tin/bằng chứng cụ thể còn thiếu] để đối chiếu.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','VERIFY_REFERENCE','REVIEW_REQUIRED','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.','["Viện dẫn nguyên văn và vị trí","Mã lý do và bằng chứng nguồn","Mốc và phạm vi đang đánh giá","Căn cứ chuyển tiếp/ngoại lệ nếu có","Hành động phù hợp trạng thái; thiếu gì yêu cầu đúng thứ đó"]','{"citation_does_not_drive_retrieval":true,"current_status_separate_from_historical":true,"human_review_required":true,"legal_basis_must_be_resolved":true,"no_auto_invalidity_or_fine":true,"no_auto_replace_old_law":true,"no_automatic_invalidity":true,"no_invented_replacement":true,"no_similarity_only_identity":true,"official_identity_and_temporal_evidence_required":true,"unknown_is_not_invalid":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_DOMAIN_MISMATCH','CITATION','DOMAIN_MISMATCH','Rà soát Điều/Khoản đang được viện dẫn cho đúng loại giao dịch, chủ thể, tài sản và vấn đề pháp lý. Nêu rõ điều kiện hoặc ngoại lệ bị bỏ qua; lựa chọn căn cứ thay thế phải do nhánh Applicable Law xác định độc lập.','[DỰ THẢO] Căn cứ [nguyên văn] đang được dùng cho [vấn đề pháp lý] chưa phù hợp [phạm vi/ngoại lệ có nguồn]. Đề nghị rà soát và diễn đạt lại căn cứ đúng phạm vi, không suy ra toàn hợp đồng vô hiệu.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','CORRECT_REFERENCE','LOW','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.','["Viện dẫn nguyên văn và vị trí","Mã lý do và bằng chứng nguồn","Mốc và phạm vi đang đánh giá","Căn cứ chuyển tiếp/ngoại lệ nếu có","Hành động phù hợp trạng thái; thiếu gì yêu cầu đúng thứ đó"]','{"citation_does_not_drive_retrieval":true,"current_status_separate_from_historical":true,"human_review_required":true,"legal_basis_must_be_resolved":true,"no_auto_invalidity_or_fine":true,"no_auto_replace_old_law":true,"no_automatic_invalidity":true,"no_invented_replacement":true,"no_similarity_only_identity":true,"official_identity_and_temporal_evidence_required":true,"unknown_is_not_invalid":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC018_01_MISSING','COMPLIANCE','MISSING','Bổ sung vào hợp đồng điều khoản thể hiện đúng yêu cầu: Hợp đồng phải ghi tên của bên bán và bên mua. (căn cứ 66/2014/QH13; Điều 18 khoản 1). Mục tiêu chỉ là tiêu chí TC_PV_HYC018_01. Hợp đồng đã ký cần sửa đổi bằng phụ lục/văn bản hợp lệ và lưu chứng cứ.','Điều [số]. [Nội dung thể hiện: Hợp đồng phải ghi tên của bên bán và bên mua.] – theo 66/2014/QH13; Điều 18 khoản 1.','Kiểm tra lại TC_PV_HYC018_01 với đúng nguồn/phiên bản lịch sử (66/2014/QH13; Điều 18 khoản 1) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','ADD','HIGH','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC018_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể; trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Hợp đồng phải ghi tên của bên bán và bên mua.","Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể","trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC018_01_VIOLATED','COMPLIANCE','VIOLATED','Sửa đổi hoặc loại bỏ nội dung trái yêu cầu để đáp ứng: Hợp đồng phải ghi tên của bên bán và bên mua. (căn cứ 66/2014/QH13; Điều 18 khoản 1); nếu là nghĩa vụ thực hiện thì thực hiện biện pháp khắc phục và lưu chứng từ. Mục tiêu chỉ là tiêu chí TC_PV_HYC018_01.','Điều [số] được sửa lại như sau: "[nội dung phù hợp với 66/2014/QH13; Điều 18 khoản 1]".','Kiểm tra lại TC_PV_HYC018_01 với đúng nguồn/phiên bản lịch sử (66/2014/QH13; Điều 18 khoản 1) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC018_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể; trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Hợp đồng phải ghi tên của bên bán và bên mua.","Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể","trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC018_01_UNKNOWN','COMPLIANCE','UNKNOWN','Yêu cầu hồ sơ để làm rõ đúng tiêu chí: Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ cần: Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể; trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.. Chưa sửa điều khoản hoặc kết luận vi phạm khi thiếu căn cứ.','Chưa đủ căn cứ đánh giá TC_PV_HYC018_01. Cần cung cấp [tài liệu còn thiếu thuộc tiêu chí] và xác nhận [mốc/ngoại lệ chưa rõ].','Kiểm tra lại TC_PV_HYC018_01 với đúng nguồn/phiên bản lịch sử (66/2014/QH13; Điều 18 khoản 1) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','REQUEST_VERIFICATION','REVIEW_REQUIRED','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC018_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể; trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Hợp đồng phải ghi tên của bên bán và bên mua.","Chỉ kiểm tra Hợp đồng phải ghi tên của bên bán và bên mua. Hồ sơ liên quan: tên đầy đủ của bên bán (doanh nghiệp) và bên mua (cá nhân/tổ chức) tại phần chủ thể","trang ký. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC018_02_MISSING','COMPLIANCE','MISSING','Bổ sung vào hợp đồng điều khoản thể hiện đúng yêu cầu: Hợp đồng phải ghi địa chỉ của bên bán và bên mua. (căn cứ 66/2014/QH13; Điều 18 khoản 1). Mục tiêu chỉ là tiêu chí TC_PV_HYC018_02. Hợp đồng đã ký cần sửa đổi bằng phụ lục/văn bản hợp lệ và lưu chứng cứ.','Điều [số]. [Nội dung thể hiện: Hợp đồng phải ghi địa chỉ của bên bán và bên mua.] – theo 66/2014/QH13; Điều 18 khoản 1.','Kiểm tra lại TC_PV_HYC018_02 với đúng nguồn/phiên bản lịch sử (66/2014/QH13; Điều 18 khoản 1) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','ADD','HIGH','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC018_02','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Hợp đồng phải ghi địa chỉ của bên bán và bên mua. Hồ sơ liên quan: địa chỉ trụ sở bên bán; địa chỉ thường trú/liên hệ bên mua tại phần chủ thể. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Hợp đồng phải ghi địa chỉ của bên bán và bên mua.","Chỉ kiểm tra Hợp đồng phải ghi địa chỉ của bên bán và bên mua. Hồ sơ liên quan: địa chỉ trụ sở bên bán","địa chỉ thường trú/liên hệ bên mua tại phần chủ thể. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_place