INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC019_02_MISSING','COMPLIANCE','MISSING','Bổ sung vào hợp đồng điều khoản thể hiện đúng yêu cầu: Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích). (căn cứ 66/2014/QH13; Điều 18 khoản 2). Mục tiêu chỉ là tiêu chí TC_PV_HYC019_02. Hợp đồng đã ký cần sửa đổi bằng phụ lục/văn bản hợp lệ và lưu chứng cứ.','Điều [số]. [Nội dung thể hiện: Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích).] – theo 66/2014/QH13; Điều 18 khoản 2.','Kiểm tra lại TC_PV_HYC019_02 với đúng nguồn/phiên bản lịch sử (66/2014/QH13; Điều 18 khoản 2) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','ADD','HIGH','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC019_02','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích). Hồ sơ liên quan: diện tích căn hộ; loại diện tích (sàn/sử dụng); phụ lục mô tả đặc điểm; trang thiết bị nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích).","Chỉ kiểm tra Hợp đồng phải có thông tin về đặc điểm của căn hộ mua bán (tối thiểu diện tích căn hộ và cách ghi nhận diện tích). Hồ sơ liên quan: diện tích căn hộ","loại diện tích (sàn/sử dụng)","phụ lục mô tả đặc điểm","trang thiết bị nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"