INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC037_02_VIOLATED','COMPLIANCE','VIOLATED','Sửa đổi hoặc loại bỏ nội dung trái yêu cầu để đáp ứng: Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua. (căn cứ 66/2014/QH13; Điều 57 khoản 1); nếu là nghĩa vụ thực hiện thì thực hiện biện pháp khắc phục và lưu chứng từ. Mục tiêu chỉ là tiêu chí TC_PV_HYC037_02.','Điều [số] được sửa lại như sau: "[nội dung phù hợp với 66/2014/QH13; Điều 57 khoản 1]".','Kiểm tra lại TC_PV_HYC037_02 với đúng nguồn/phiên bản lịch sử (66/2014/QH13; Điều 57 khoản 1) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC037_02','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua. Hồ sơ liên quan: điều khoản đợt thanh toán cuối; sự kiện kích hoạt đợt cuối; ngoại lệ (bên mua tự làm thủ tục; chậm nộp hồ sơ); phụ lục thanh toán. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua.","Chỉ kiểm tra Phần giá trị còn lại của hợp đồng chỉ đến hạn thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp Giấy chứng nhận cho bên mua. Hồ sơ liên quan: điều khoản đợt thanh toán cuối","sự kiện kích hoạt đợt cuối","ngoại lệ (bên mua tự làm thủ tục","chậm nộp hồ sơ)","phụ lục thanh toán. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
