INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_HYC049_01_MISSING','COMPLIANCE','MISSING','Bổ sung vào hợp đồng điều khoản thể hiện đúng yêu cầu: Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung. (căn cứ 65/2014/QH13; Điều 108 khoản 1 điểm a). Mục tiêu chỉ là tiêu chí TC_PV_HYC049_01. Hợp đồng đã ký cần sửa đổi bằng phụ lục/văn bản hợp lệ và lưu chứng cứ.','Điều [số]. [Nội dung thể hiện: Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung.] – theo 65/2014/QH13; Điều 108 khoản 1 điểm a.','Kiểm tra lại TC_PV_HYC049_01 với đúng nguồn/phiên bản lịch sử (65/2014/QH13; Điều 108 khoản 1 điểm a) và bằng chứng đã bổ sung; đối chiếu toàn bộ hợp đồng và phụ lục.','AI_DRAFT_PENDING_HUMAN','ADD','HIGH','AI_DRAFT_PENDING_HUMAN','SOURCE_LINKED_AI_DRAFT','TC_PV_HYC049_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. Chỉ kiểm tra Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung. Hồ sơ liên quan: điều khoản kinh phí bảo trì; số tiền/tỷ lệ; căn cứ tính; thời điểm nộp; tài khoản nhận; phụ lục giá. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','["Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung.","Chỉ kiểm tra Hợp đồng mua bán căn hộ do chủ đầu tư bán phải quy định rõ khoản kinh phí bảo trì phần sở hữu chung. Hồ sơ liên quan: điều khoản kinh phí bảo trì","số tiền/tỷ lệ","căn cứ tính","thời điểm nộp","tài khoản nhận","phụ lục giá. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"leg