hà ở vào sử dụng. Hồ sơ liên quan: mốc bắt đầu bảo hành ghi trong HĐ (nghiệm thu","bàn giao căn hộ","ngày cố định)","ngày nghiệm thu nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung."]','{"criterion_target_only":true,"legal_basis_must_resolve":true,"no_auto_invalidity_or_fine":true,"no_invented_names_dates_accounts":true,"not_applicable_no_remedy":true,"quote_must_match_source":true,"recommendation_null_if_satisfied":true,"related_elements_are_context_not_all_mandatory":true,"scope_required":true,"severity_from_db":true,"template_values_are_placeholders":true,"unknown_is_verification_not_violation":true}') ON CONFLICT ("khuyen_nghi_id") DO NOTHING;
